import { mountEmbeddedPage } from '../runtime/embedded-page.js';

const pageHtml = "<!DOCTYPE html>\n<html lang=\"zh-TW\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n  <title>四季農莊：島嶼物語</title>\n  <link rel=\"stylesheet\" href=\"farm-ui.css\">\n  \n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <script crossorigin src=\"https://unpkg.com/react@18/umd/react.production.min.js\"></script>\n  <script crossorigin src=\"https://unpkg.com/react-dom@18/umd/react-dom.production.min.js\"></script>\n  <script src=\"https://unpkg.com/@babel/standalone@7.26.10/babel.min.js\"></script>\n</head>\n<body class=\"bg-slate-900 overflow-x-hidden\">\n  \n  <div id=\"root\"></div>\n\n  <script type=\"text/babel\">\n    const { useState, useEffect, useCallback, useRef } = React;\n\n    // --- 音效引擎 ---\n    const useAudio = () => {\n      const audioCtx = useRef(null);\n      const initAudio = () => {\n        if (!audioCtx.current) {\n          audioCtx.current = new (window.AudioContext || window.webkitAudioContext)();\n        }\n      };\n\n      const playEffect = (type) => {\n        initAudio();\n        const now = audioCtx.current.currentTime;\n        \n        if (type === 'water') {\n          const osc = audioCtx.current.createOscillator();\n          const gain = audioCtx.current.createGain();\n          osc.type = 'sine';\n          osc.frequency.setValueAtTime(800, now);\n          osc.frequency.exponentialRampToValueAtTime(100, now + 0.1);\n          gain.gain.setValueAtTime(0.3, now);\n          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);\n          osc.connect(gain);\n          gain.connect(audioCtx.current.destination);\n          osc.start();\n          osc.stop(now + 0.1);\n        } else if (type === 'weed') {\n          const bufferSize = audioCtx.current.sampleRate * 0.1;\n          const buffer = audioCtx.current.createBuffer(1, bufferSize, audioCtx.current.sampleRate);\n          const data = buffer.getChannelData(0);\n          for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;\n          const noise = audioCtx.current.createBufferSource();\n          noise.buffer = buffer;\n          const filter = audioCtx.current.createBiquadFilter();\n          filter.type = 'highpass';\n          filter.frequency.value = 1000;\n          const gain = audioCtx.current.createGain();\n          gain.gain.setValueAtTime(0.2, now);\n          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);\n          noise.connect(filter);\n          filter.connect(gain);\n          gain.connect(audioCtx.current.destination);\n          noise.start();\n        } else if (type === 'coin') {\n          const osc = audioCtx.current.createOscillator();\n          const gain = audioCtx.current.createGain();\n          osc.frequency.setValueAtTime(1200, now);\n          osc.frequency.exponentialRampToValueAtTime(1500, now + 0.3);\n          gain.gain.setValueAtTime(0.5, now); \n          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.4);\n          osc.connect(gain);\n          gain.connect(audioCtx.current.destination);\n          osc.start();\n          osc.stop(now + 0.4);\n        }\n      };\n\n      return { playEffect };\n    };\n\n    // --- 自定義 UI 元件：手繪尖刺雜草 ---\n    const WeedIcon = ({ className }) => (\n      <svg viewBox=\"0 0 100 100\" className={className} xmlns=\"http://www.w3.org/2000/svg\">\n        <path \n          d=\"M 25 85 Q 20 60 10 45 Q 30 50 40 65 Q 45 30 50 20 Q 55 30 60 60 Q 80 40 90 35 Q 80 60 75 85 Z\" \n          fill=\"#16a34a\" \n          stroke=\"#14532d\" \n          strokeWidth=\"6\" \n          strokeLinejoin=\"round\" \n          strokeLinecap=\"round\" \n        />\n      </svg>\n    );\n\n    // --- 自定義 UI 元件：專屬肥料袋 ---\n    const FertilizerBag = ({ type }) => {\n      const config = {\n        leaf: { bg: 'bg-green-500', top: 'bg-green-600', text: '葉菜', tie: 'bg-amber-800' },\n        root: { bg: 'bg-yellow-600', top: 'bg-yellow-700', text: '根莖', tie: 'bg-amber-900' },\n        fruit: { bg: 'bg-purple-500', top: 'bg-purple-600', text: '瓜果', tie: 'bg-purple-900' }\n      }[type];\n\n      return (\n        <div className=\"flex flex-col items-center justify-end w-9 h-10 drop-shadow-md transition-transform\">\n          <div className={`w-5 h-2 ${config.top} rounded-t-sm`}></div>\n          <div className={`w-6 h-1.5 ${config.tie} rounded-full z-10 -my-[2px] shadow-sm`}></div>\n          <div className={`w-8 h-7 ${config.bg} rounded-b-xl rounded-t-sm flex items-center justify-center shadow-[inset_0_-3px_4px_rgba(0,0,0,0.3)] pb-0.5`}>\n            <span className=\"text-[9px] font-black text-white/95 leading-none tracking-tighter drop-shadow-sm\">{config.text}</span>\n          </div>\n        </div>\n      );\n    };\n\n    // --- 自定義 UI 元件：專屬種子袋 ---\n    const SeedBag = ({ crop }) => {\n      const isSpecial = crop.price === 0;\n      return (\n        <div className={`flex flex-col items-center justify-end w-9 h-10 drop-shadow-md transition-transform relative ${isSpecial ? 'animate-pulse scale-110' : ''}`}>\n          <div className={`w-5 h-2 ${isSpecial ? 'bg-yellow-300' : 'bg-amber-700'} rounded-t-sm`}></div>\n          <div className={`w-6 h-1.5 ${isSpecial ? 'bg-red-500' : 'bg-amber-900'} rounded-full z-10 -my-[2px] shadow-sm`}></div>\n          <div className={`w-8 h-7 ${isSpecial ? 'bg-gradient-to-br from-yellow-300 via-yellow-500 to-orange-500 border border-yellow-200' : 'bg-amber-600'} rounded-b-xl rounded-t-sm flex items-center justify-center shadow-[inset_0_-3px_4px_rgba(0,0,0,0.3)] pb-0.5 overflow-hidden relative`}>\n            {isSpecial && <div className=\"absolute inset-0 bg-white/40 animate-ping rounded-b-xl\"></div>}\n            <span className=\"text-[12px] leading-none drop-shadow-md z-10\">{crop.icon}</span>\n          </div>\n          {isSpecial && <span className=\"absolute -top-1 -right-2 text-[12px] animate-bounce drop-shadow-lg\">✨</span>}\n        </div>\n      );\n    };\n\n    // --- 作物數據設定 ---\n    const CROPS = {\n      SPRING: [\n        { id: 'sweetpotatoleaf', name: '地瓜葉', type: 'leaf', price: 100, days: 3, value: 40, icon: '🌿', desc: '【環境】喜高溫多濕，對土壤適應性極強。\\n【種植】多以扦插繁殖，生長迅速，需保持土壤濕潤，不需過度施肥即可旺盛生長。' },\n        { id: 'bokchoy', name: '青江菜', type: 'leaf', price: 500, days: 4, value: 150, icon: '🥬', desc: '【環境】喜冷涼氣候，日照需充足。\\n【種植】種子直播，因根系較淺需勤澆水保持濕潤。極易受十字花科害蟲啃食，需注重防蟲。' },\n        { id: 'guava', name: '芭樂', type: 'fruit', price: 1500, days: 8, value: 500, icon: '🍐', desc: '【環境】需全日照，喜好排水良好的砂質壤土。\\n【種植】需定時修剪枝條以促進開花結果，適度施用磷鉀肥可大幅提升果實甜度與脆度。' },\n      ],\n      SUMMER: [\n        { id: 'waterspinach', name: '空心菜', type: 'leaf', price: 200, days: 3, value: 80, icon: '🥬', desc: '【環境】極度喜高溫與潮濕，耐澇性強。\\n【種植】播種或扦插皆可，莖部中空能適應積水環境。只要水分充足，夏天生長速度極快。' },\n        { id: 'loofah', name: '絲瓜', type: 'fruit', price: 800, days: 6, value: 250, icon: '🥒', desc: '【環境】喜高溫多濕，不耐寒，需搭設棚架。\\n【種植】攀藤生長，開花後需人工或仰賴昆蟲授粉。必須在果實鮮嫩時採收。' },\n        { id: 'mango', name: '芒果', type: 'fruit', price: 2500, days: 12, value: 800, icon: '🥭', desc: '【環境】熱帶果樹，喜高溫乾燥，需充足日照。\\n【種植】開花期極忌連續降雨會導致落花。果實發育期需套袋，防止蟲害與烈日曬傷。' },\n      ],\n      AUTUMN: [\n        { id: 'waterbamboo', name: '筊白筍', type: 'root', price: 400, days: 5, value: 150, icon: '🎋', desc: '【環境】需生長於水溫穩定、活水流動的淺水田中。\\n【種植】實為菰草受「黑穗菌」共生感染後膨大的幼嫩莖部。水質控制是絕對關鍵。' },\n        { id: 'taro', name: '芋頭', type: 'root', price: 1500, days: 9, value: 500, icon: '🥔', desc: '【環境】喜高溫多濕，栽培分為水芋與旱芋兩種。\\n【種植】生長期長，需深厚且保水力強的土壤。屬於重肥作物，生長期間需大量養分。' },\n        { id: 'pomelo', name: '文旦', type: 'fruit', price: 3500, days: 15, value: 1250, icon: '🍋', desc: '【環境】喜高溫與日照，需排水良好的山坡地。\\n【種植】果樹需多年栽培。果實採收後不宜馬上食用，需放置通風處數日進行「辭水」。' },\n      ],\n      WINTER: [\n        { id: 'whiteradish', name: '蘿蔔', type: 'root', price: 600, days: 4, value: 200, icon: '🥕', desc: '【環境】喜冷涼氣候，忌高溫多濕。\\n【種植】屬根莖類，種子必須「直播」於深厚、鬆軟的土壤中，若移植或遇硬土會導致變形。' },\n        { id: 'cabbage', name: '高麗菜', type: 'leaf', price: 2000, days: 7, value: 750, icon: '🥬', desc: '【環境】極喜冷涼，高山地區日夜溫差大最為適宜。\\n【種植】結球期需要大量水分與養分，溫差越大則口感越清脆甘甜。需注意田間排水。' },\n        { id: 'strawberry', name: '草莓', type: 'fruit', price: 6000, days: 14, value: 2000, icon: '🍓', desc: '【環境】極度嬌貴，喜冷涼氣候與充足日照，怕雨水。\\n【種植】根系淺怕積水，極易染病蟲害。現代多採用高架覆膜種植，除保持通風也避免腐爛。' },\n      ],\n      SPECIAL: [\n        { id: 'golden_peach', name: '黃金仙桃', type: 'fruit', price: 0, days: 10, value: 600, icon: '🍑', desc: '【環境】春季限定的傳說果實，散發出神聖的微光。\\n【種植】相傳是天庭掉落的種子，對水分要求極高，成功收成後價值連城，是鎮長夢寐以求的極品。' },\n        { id: 'crystal_melon', name: '水晶寶石西瓜', type: 'fruit', price: 0, days: 12, value: 600, icon: '🍉', desc: '【環境】夏季限定，果肉如紅寶石般晶瑩剔透。\\n【種植】極度需要充足水分與烈日曝曬，在極端高溫下反而能凝結出絕佳的脆度與甜味。' },\n        { id: 'giant_pumpkin', name: '巨無霸南瓜', type: 'fruit', price: 0, days: 15, value: 600, icon: '🎃', desc: '【環境】秋季限定的變異品種，體積異常巨大。\\n【種植】種下後會瞬間霸佔整塊農田吸收所有養分。在田地中緩慢膨脹的過程極具視覺震撼力！' },\n        { id: 'white_strawberry', name: '初雪白草莓', type: 'fruit', price: 0, days: 14, value: 600, icon: '🍓', desc: '【環境】冬季限定，對溫度極度敏感的嬌貴品種。\\n【種植】需要在嚴寒中小心呵護，果實純白如初雪，香氣馥郁，是高級拍賣會上千金難求的珍寶。' }\n      ]\n    };\n\n    const PLOT_PRICES = [0, 5000, 15000, 30000];\n\n    const getRainProbability = (season) => {\n      switch(season) {\n        case 'SPRING': return 0.35; \n        case 'SUMMER': return 0.45; \n        case 'AUTUMN': return 0.25; \n        case 'WINTER': return 0.20; \n        default: return 0.2;\n      }\n    };\n\n    // --- 飛行作物動畫元件 ---\n    const FlyingCropComponent = ({ data, onRemove }) => {\n      const [active, setActive] = useState(false);\n      useEffect(() => {\n        const raf = requestAnimationFrame(() => {\n            requestAnimationFrame(() => setActive(true));\n        });\n        // 0.5秒後動畫結束，移除 DOM\n        const timer = setTimeout(() => onRemove(data.id), 500);\n        return () => { cancelAnimationFrame(raf); clearTimeout(timer); };\n      }, [data, onRemove]);\n\n      return (\n        <div \n            className=\"fixed z-[9999] pointer-events-none drop-shadow-2xl flex items-center justify-center\"\n            style={{\n                left: active ? data.endX : data.startX,\n                top: active ? data.endY : data.startY,\n                transform: `translate(-50%, -50%) scale(${active ? 0.3 : 1.2})`,\n                opacity: active ? 0.2 : 1,\n                transition: 'all 0.5s cubic-bezier(0.25, 1, 0.5, 1)',\n                fontSize: '4rem'\n            }}\n        >\n            {data.icon}\n        </div>\n      );\n    };\n\n    const App = () => {\n      const { playEffect } = useAudio();\n      \n      const [isGameStarted, setIsGameStarted] = useState(false);\n      const [farmName, setFarmName] = useState('');\n\n      const [day, setDay] = useState(1);\n      const [weather, setWeather] = useState('sunny'); \n      const [gold, setGold] = useState(100); \n      \n      const [tutorialStep, setTutorialStep] = useState(0); \n      const [flags, setFlags] = useState({ \n        seenRain: false, seenTyphoon: false, seenQuest: false, seenBug: false, \n        seenWeed: false, seenDay2Water: false, seenHarvest: false,\n        seenAfterHarvest: false, seenQuestReward: false, seenForgotWater: false,\n        tutSell: false, tutFert: false, tutNet: false\n      });\n\n      const [inventory, setInventory] = useState({ \n        nets: 0, windbreaks: 0, fert_leaf: 0, fert_root: 0, fert_fruit: 0, \n        scissors: 10, chili: 10, seeds: {}, crops: {} \n      }); \n      const [gallery, setGallery] = useState({}); \n      \n      const [selectedTool, setSelectedTool] = useState('water');\n      const [selectedSeed, setSelectedSeed] = useState(null);\n      \n      const [showShop, setShowShop] = useState(false); \n      const [shopTab, setShopTab] = useState('buy');\n      \n      const [schoolQuest, setSchoolQuest] = useState(null); \n      const [showQuestModal, setShowQuestModal] = useState(false);\n      \n      const [eventQueue, setEventQueue] = useState([]);\n      const currentEvent = eventQueue[0]; \n      \n      const [flyingCrops, setFlyingCrops] = useState([]);\n      const dropZoneRef = useRef(null);\n      \n      const closeEventModal = () => {\n        setEventQueue(prev => prev.slice(1)); \n      };\n      \n      const [plots, setPlots] = useState(Array(4).fill(null).map((_, i) => ({\n        id: i,\n        isUnlocked: i === 0, \n        isNetted: false,\n        isWindbreaked: false, \n        slots: Array(8).fill(null).map((_, j) => ({\n          id: j, crop: null, growth: 0, isWatered: false, isFertilized: false, hasBug: false, hasWeed: false, perfectGrowth: true\n        }))\n      })));\n      \n      const [activePlot, setActivePlot] = useState(null);\n      const [message, setMessage] = useState(\"歡迎來到 四季農莊！\");\n      const [showModal, setShowModal] = useState(null);\n      const [saveExists, setSaveExists] = useState(false);\n\n      useEffect(() => {\n        const saved = localStorage.getItem('farm_tycoon_save_v2');\n        if (saved) setSaveExists(true);\n      }, []);\n\n      useEffect(() => {\n        document.body.dataset.farmHomeHidden = isGameStarted ? 'true' : 'false';\n        return () => { delete document.body.dataset.farmHomeHidden; };\n      }, [isGameStarted]);\n\n      const removeFlyingCrop = useCallback((id) => {\n        setFlyingCrops(prev => prev.filter(c => c.id !== id));\n      }, []);\n\n      // --- 點擊收成與飛行觸發邏輯 ---\n      const handleHarvestClick = (e, plotId, slotId, crop, isGiant) => {\n        e.stopPropagation(); // 避免觸發底層的其他點擊事件\n        \n        // 取得點擊作物的起始座標\n        const rect = e.currentTarget.getBoundingClientRect();\n        const startX = rect.left + rect.width / 2;\n        const startY = rect.top + rect.height / 2;\n\n        // 取得收成箱的目標座標\n        let endX = window.innerWidth / 2;\n        let endY = 0;\n        if (dropZoneRef.current) {\n            const boxRect = dropZoneRef.current.getBoundingClientRect();\n            endX = boxRect.left + boxRect.width / 2;\n            endY = boxRect.top + boxRect.height / 2;\n        }\n\n        // 推入飛行陣列觸發動畫\n        const newId = Date.now() + Math.random();\n        setFlyingCrops(prev => [...prev, { id: newId, icon: crop.icon, startX, startY, endX, endY }]);\n\n        // 延遲播放金幣聲音，讓作物「飛到箱子」時才響\n        setTimeout(() => playEffect('coin'), 400);\n\n        // 立即處理後台收成邏輯\n        processHarvest(plotId, slotId, crop, isGiant);\n      };\n\n      const processHarvest = (plotId, slotId, crop, isGiant) => {\n        const newPlots = JSON.parse(JSON.stringify(plots));\n        const targetPlot = newPlots[plotId];\n        \n        if (isGiant) {\n          targetPlot.slots.forEach(s => { \n            s.crop = null; s.growth = 0; s.hasBug = false; s.hasWeed = false; s.isFertilized = false; s.perfectGrowth = true; \n          });\n        } else {\n          const s = targetPlot.slots[slotId];\n          s.crop = null; s.growth = 0; s.hasBug = false; s.hasWeed = false; s.isFertilized = false; s.perfectGrowth = true; \n        }\n\n        setPlots(newPlots);\n\n        // 檢查收成後，畫面上是否還有其他「已經成熟」的作物\n        const remainingMature = newPlots.some(p => p.slots.some(s => s.crop && s.growth >= s.crop.days));\n\n        setGallery(prevG => ({\n          ...prevG,\n          [crop.id]: { unlocked: true, perfect: prevG[crop.id]?.perfect || true } \n        }));\n\n        setInventory(inv => ({\n          ...inv,\n          crops: { ...inv.crops, [crop.id]: (inv.crops?.[crop.id] || 0) + 1 }\n        }));\n\n        setMessage(`✨ 收成了 ${crop.name}！已存入倉庫，請至商店變現。`);\n\n        // 當畫面上的成熟作物全部被清空時，才觸發第一次收成獎勵與進階教學\n        setFlags(prev => {\n          if (!prev.seenAfterHarvest && !remainingMature) {\n            setEventQueue(q => [...q, { type: 'tutorial_after_harvest' }]);\n            setInventory(inv => ({ ...inv, fert_leaf: (inv.fert_leaf||0) + 1, nets: (inv.nets||0) + 1 }));\n            setTutorialStep(7); // 開啟進階任務1：販賣教學\n            return { ...prev, seenAfterHarvest: true };\n          }\n          return prev;\n        });\n      };\n\n      useEffect(() => {\n        if (tutorialStep === 2 && (inventory.seeds['sweetpotatoleaf'] || 0) > 0) setTutorialStep(3);\n        if (tutorialStep === 3 && selectedTool === 'seed' && selectedSeed?.id === 'sweetpotatoleaf') setTutorialStep(4);\n        if (tutorialStep === 4 && plots[0].slots.some(s => s.crop)) setTutorialStep(5);\n        if (tutorialStep === 5) {\n          const plantedSlots = plots[0].slots.filter(s => s.crop);\n          if (plantedSlots.length > 0 && plantedSlots.every(s => s.isWatered)) {\n            setTutorialStep(6);\n          }\n        }\n        if (tutorialStep === 6 && day > 1) setTutorialStep(0);\n      }, [tutorialStep, inventory.seeds, selectedTool, selectedSeed, plots, day]);\n\n      // 新增：進階任務檢查 (自由順序完成)\n      useEffect(() => {\n        if (tutorialStep >= 7 && flags.tutSell && flags.tutFert && flags.tutNet) {\n          setTutorialStep(0);\n          setMessage(\"🎉 恭喜完成所有進階教學！現在你可以自由經營你的農莊了！\");\n          playEffect('coin');\n        }\n      }, [tutorialStep, flags.tutSell, flags.tutFert, flags.tutNet, playEffect]);\n\n      const handleSave = () => {\n        try {\n          const stateToSave = {\n            isGameStarted, farmName, day, weather, gold, inventory, gallery, plots, schoolQuest, flags, tutorialStep\n          };\n          localStorage.setItem('farm_tycoon_save_v2', JSON.stringify(stateToSave));\n          setMessage(\"💾 遊戲進度已成功儲存！\");\n          setSaveExists(true);\n          playEffect('coin');\n          setShowModal(null);\n        } catch (e) {\n          setMessage(\"❌ 存檔失敗，請確認瀏覽器設定。\");\n        }\n      };\n\n      const handleLoad = () => {\n        try {\n          const saved = localStorage.getItem('farm_tycoon_save_v2');\n          if (saved) {\n            const state = JSON.parse(saved);\n            setIsGameStarted(state.isGameStarted);\n            setFarmName(state.farmName);\n            setDay(state.day);\n            setWeather(state.weather);\n            setGold(state.gold);\n            setInventory({ ...state.inventory, crops: state.inventory.crops || {} });\n            setGallery(state.gallery || {});\n            setPlots(state.plots);\n            setSchoolQuest(state.schoolQuest);\n            setFlags(state.flags || { seenRain: false, seenTyphoon: false, seenQuest: false, seenBug: false, seenWeed: false, seenDay2Water: false, seenHarvest: false, seenAfterHarvest: false, seenQuestReward: false, seenForgotWater: false, tutSell: false, tutFert: false, tutNet: false });\n            setTutorialStep(state.tutorialStep || 0);\n            \n            setMessage(\"📂 遊戲進度讀取成功！歡迎回來！\");\n            setShowModal(null);\n            setEventQueue([]); \n            setActivePlot(null);\n            playEffect('water');\n          }\n        } catch (e) {\n          setMessage(\"❌ 讀檔失敗，存檔資料可能已損毀。\");\n        }\n      };\n\n      const season = day <= 90 ? 'SPRING' : day <= 180 ? 'SUMMER' : day <= 270 ? 'AUTUMN' : 'WINTER';\n      const seasonName = { SPRING: '春', SUMMER: '夏', AUTUMN: '秋', WINTER: '冬' }[season];\n      const seasonColor = { SPRING: 'bg-green-100', SUMMER: 'bg-yellow-100', AUTUMN: 'bg-orange-100', WINTER: 'bg-blue-100' }[season];\n\n      const processNextDay = () => {\n        if (day >= 365) {\n          setShowModal('result');\n          return;\n        }\n        \n        let hasDeadCrops = false;\n        let typhoonDamageCount = 0;\n        \n        const nextDayNum = day + 1;\n        const nextSeason = nextDayNum <= 90 ? 'SPRING' : nextDayNum <= 180 ? 'SUMMER' : nextDayNum <= 270 ? 'AUTUMN' : 'WINTER';\n        \n        const isTyphoonNext = (nextSeason === 'SUMMER' || nextSeason === 'AUTUMN') && Math.random() < 0.08;\n        const isRainingNext = nextDayNum > 3 ? Math.random() < getRainProbability(nextSeason) : false;\n        const nextWeatherType = isTyphoonNext ? 'typhoon' : (isRainingNext ? 'rainy' : 'sunny');\n\n        // 在處理下一天前，檢查今天是否有生長中的作物「忘記澆水」\n        const forgotWaterYesterday = plots.some(p => p.slots.some(s => s.crop && s.growth < s.crop.days && !s.isWatered));\n\n        const nextPlots = plots.map(plot => {\n          const updatedSlots = plot.slots.map(slot => {\n            if (!slot.crop) return slot;\n            \n            const isMature = slot.growth >= slot.crop.days;\n            \n            if (weather === 'typhoon' && !plot.isWindbreaked && !isMature) {\n              if (Math.random() < 0.5) { \n                typhoonDamageCount++;\n                return { id: slot.id, crop: null, growth: 0, isWatered: false, isFertilized: false, hasBug: false, hasWeed: false, perfectGrowth: true };\n              }\n            }\n\n            if (slot.hasBug || slot.hasWeed) {\n              hasDeadCrops = true;\n              return { id: slot.id, crop: null, growth: 0, isWatered: false, isFertilized: false, hasBug: false, hasWeed: false, perfectGrowth: true };\n            }\n\n            let newGrowth = slot.growth;\n            let stillPerfect = slot.perfectGrowth;\n            let bug = slot.hasBug;\n            let weed = slot.hasWeed;\n\n            if (!isMature) {\n              if (!plot.isNetted && !bug && Math.random() < 0.15) { bug = true; stillPerfect = false; }\n              if (!weed && Math.random() < 0.2) { weed = true; stillPerfect = false; }\n            }\n\n            if (slot.isWatered || weather === 'typhoon') {\n              newGrowth += 1;\n            } \n            \n            if (!slot.isWatered && weather !== 'typhoon' || bug || weed) {\n              stillPerfect = false;\n            }\n\n            return { \n              ...slot, \n              growth: newGrowth, \n              isWatered: (nextWeatherType === 'rainy' || nextWeatherType === 'typhoon') ? true : false, \n              isFertilized: false, \n              hasBug: bug, \n              hasWeed: weed, \n              perfectGrowth: stillPerfect \n            };\n          });\n\n          const hasMatureCrop = updatedSlots.some(s => s.crop && s.growth >= s.crop.days);\n\n          return {\n            ...plot,\n            isNetted: hasMatureCrop ? false : plot.isNetted,\n            slots: updatedSlots\n          };\n        });\n\n        const currentHasBug = nextPlots.some(p => p.slots.some(s => s.hasBug));\n        const currentHasWeed = nextPlots.some(p => p.slots.some(s => s.hasWeed));\n        const currentHasMature = nextPlots.some(p => p.slots.some(s => s.crop && s.growth >= s.crop.days));\n\n        setPlots(nextPlots);\n        \n        let newQuest = null;\n        if (schoolQuest) {\n          setSchoolQuest(prev => (prev && prev.daysLeft > 1) ? { ...prev, daysLeft: prev.daysLeft - 1 } : null);\n        } else {\n          if (nextDayNum > 5 && Math.random() < 0.15) { \n            const seasonCrops = CROPS[nextSeason].slice(0, 2); \n            const randomCrop = seasonCrops[Math.floor(Math.random() * seasonCrops.length)];\n            newQuest = { crop: randomCrop, required: 8, daysLeft: 5 }; \n            setSchoolQuest(newQuest);\n          }\n        }\n\n        setDay(nextDayNum);\n        setWeather(nextWeatherType);\n        setShowModal(null);\n        \n        let newEvents = [];\n\n        // 若第一次忘記澆水，推入提示事件\n        if (forgotWaterYesterday && !flags.seenForgotWater) {\n          newEvents.push({ type: 'tutorial_forgot_water' });\n          setFlags(prev => ({...prev, seenForgotWater: true}));\n        }\n\n        if (nextDayNum === 2 && !flags.seenDay2Water) {\n          newEvents.push({ type: 'tutorial_day2_water' });\n          setFlags(prev => ({...prev, seenDay2Water: true}));\n        }\n        if (currentHasBug && !flags.seenBug) {\n          newEvents.push({ type: 'tutorial_bug' });\n          setFlags(prev => ({...prev, seenBug: true}));\n        }\n        if (currentHasWeed && !flags.seenWeed) {\n          newEvents.push({ type: 'tutorial_weed' });\n          setFlags(prev => ({...prev, seenWeed: true}));\n        }\n        if (currentHasMature && !flags.seenHarvest) {\n          newEvents.push({ type: 'tutorial_harvest' });\n          setFlags(prev => ({...prev, seenHarvest: true}));\n        }\n        if (nextWeatherType === 'rainy' && !flags.seenRain) {\n          newEvents.push({ type: 'tutorial_rain' });\n          setFlags(prev => ({...prev, seenRain: true}));\n        }\n        if (hasDeadCrops) {\n          newEvents.push({ type: 'crop_died' });\n        }\n\n        if (nextDayNum === 20) {\n          newEvents.push({ type: 'irrigation_upgrade' });\n        }\n        if (isTyphoonNext) {\n          newEvents.push({ type: 'typhoon_warning', isFirst: !flags.seenTyphoon });\n          if (!flags.seenTyphoon) {\n            setFlags(prev => ({...prev, seenTyphoon: true}));\n            // 新手教學：第一次遇到颱風送 1 個防風網\n            setInventory(inv => ({ ...inv, windbreaks: (inv.windbreaks || 0) + 1 }));\n          }\n        }\n        if (typhoonDamageCount > 0) {\n          newEvents.push({ type: 'typhoon_damage', count: typhoonDamageCount });\n        }\n        if (newQuest) {\n          newEvents.push({ type: 'school_quest', data: newQuest });\n          if (!flags.seenQuest) setFlags(prev => ({...prev, seenQuest: true}));\n        }\n        \n        setEventQueue(newEvents);\n\n        if (typhoonDamageCount > 0) {\n          setMessage(`😭 災情回報：昨晚的颱風摧毀了你 ${typhoonDamageCount} 株缺乏保護的作物！`);\n          playEffect('weed');\n        } else if (hasDeadCrops) {\n          setMessage(\"警告：有作物因為未處理蟲害或雜草而枯死了！\");\n          playEffect('weed');\n        } else {\n          if (nextWeatherType === 'typhoon') {\n            setMessage(`第 ${nextDayNum} 天颱風來襲 🌀！外面狂風暴雨，農田自動澆滿水了。`);\n          } else if (nextWeatherType === 'rainy') {\n            setMessage(`第 ${nextDayNum} 天早安！今天下雨了 🌧️，田地都已經自動吸滿水份囉！`);\n          } else {\n            setMessage(`第 ${nextDayNum} 天早安！晴空萬里 ☀️，別忘了幫作物澆水喔。`);\n          }\n        }\n        \n        if (nextDayNum % 100 === 0 && nextDayNum <= 300) setShowModal('contest');\n      };\n\n      const handleSlotClick = (plotId, slotId) => {\n        setPlots(prev => {\n          const newPlots = JSON.parse(JSON.stringify(prev));\n          const targetPlot = newPlots[plotId];\n          const targetSlot = targetPlot.slots[slotId];\n\n          if (!targetPlot.isUnlocked) return prev; \n          \n          const isGiantPumpkin = targetPlot.slots[0]?.crop?.id === 'giant_pumpkin';\n\n          if (selectedTool === 'water') {\n            let wateredAny = false;\n            if (day >= 20 || isGiantPumpkin) {\n              targetPlot.slots.forEach(s => {\n                if (s.crop && !s.isWatered) {\n                  s.isWatered = true;\n                  wateredAny = true;\n                }\n              });\n\n              if (!wateredAny) {\n                setMessage(weather === 'rainy' ? \"今天是雨天，不需要人工澆水喔！\" : \"此區塊目前沒有需要澆水的作物！\");\n                return prev; \n              }\n              playEffect('water');\n              setMessage(`💦 灑水完成！第 ${plotId + 1} 區的作物皆已吸滿水分！`);\n            } else {\n              if (targetSlot.crop && !targetSlot.isWatered) {\n                targetSlot.isWatered = true;\n                wateredAny = true;\n              }\n              if (!wateredAny) {\n                setMessage(weather === 'rainy' ? \"今天是雨天，不需要人工澆水喔！\" : \"這格沒有需要澆水的作物！\");\n                return prev; \n              }\n              playEffect('water');\n              setMessage(`💧 已為該格作物澆水！`);\n            }\n          } \n          \n          else if (selectedTool === 'weed') {\n            if (isGiantPumpkin) {\n              const hasAnyWeed = targetPlot.slots.some(s => s.hasWeed);\n              if (!hasAnyWeed) return prev;\n              if (inventory.scissors <= 0) {\n                setMessage(\"除草剪刀已完全損壞，請至商店購買新的剪刀！\");\n                return prev;\n              }\n              targetPlot.slots.forEach(s => s.hasWeed = false);\n              setInventory(inv => ({ ...inv, scissors: inv.scissors - 1 }));\n              playEffect('weed');\n              setMessage(`✨ 割除巨無霸南瓜周圍的雜草成功！(剪刀剩餘 ${inventory.scissors - 1} 次)`);\n            } else {\n              if (!targetSlot.hasWeed) return prev; \n              if (inventory.scissors <= 0) {\n                setMessage(\"除草剪刀已完全損壞，請至商店購買新的剪刀！\");\n                return prev;\n              }\n              targetSlot.hasWeed = false;\n              setInventory(inv => ({ ...inv, scissors: inv.scissors - 1 }));\n              playEffect('weed');\n              setMessage(`✨ 割除雜草成功！(剪刀剩餘 ${inventory.scissors - 1} 次)`);\n            }\n          } \n          \n          else if (selectedTool === 'chili') {\n            if (isGiantPumpkin) {\n              const hasAnyBug = targetPlot.slots.some(s => s.hasBug);\n              if (!hasAnyBug) return prev;\n              if (inventory.chili <= 0) {\n                setMessage(\"辣椒水已耗盡，請至商店購買補充包！\");\n                return prev;\n              }\n              targetPlot.slots.forEach(s => s.hasBug = false);\n              setInventory(inv => ({ ...inv, chili: inv.chili - 1 }));\n              playEffect('water'); \n              setMessage(`✨ 成功驅除巨無霸南瓜上的害蟲！(剩餘 ${inventory.chili - 1} 次)`);\n            } else {\n              if (!targetSlot.hasBug) return prev; \n              if (inventory.chili <= 0) {\n                setMessage(\"辣椒水已耗盡，請至商店購買補充包！\");\n                return prev;\n              }\n              targetSlot.hasBug = false;\n              setInventory(inv => ({ ...inv, chili: inv.chili - 1 }));\n              playEffect('water'); \n              setMessage(`✨ 噴灑辣椒水驅蟲成功！(剩餘 ${inventory.chili - 1} 次)`);\n            }\n          } \n          \n          else if (selectedTool.startsWith('fert_')) {\n            const fertType = selectedTool.split('_')[1]; \n            const fertNames = { leaf: '氮肥', root: '磷肥', fruit: '鉀肥' };\n            const fertName = fertNames[fertType];\n\n            if (inventory[selectedTool] <= 0) {\n              setMessage(`${fertName}庫存不足，請去商店購買！`);\n              return prev;\n            }\n\n            let fertilizedAny = false;\n            let alreadyFertilizedAny = false;\n            let wrongTypeAny = false;\n            \n            targetPlot.slots.forEach(s => {\n              if (s.crop && s.growth < s.crop.days) {\n                if (s.crop.type === fertType) {\n                  if (!s.isFertilized) {\n                    s.growth += 1;\n                    s.isFertilized = true; \n                    fertilizedAny = true;\n                  } else {\n                    alreadyFertilizedAny = true; \n                  }\n                } else {\n                  wrongTypeAny = true;\n                }\n              }\n            });\n\n            if (!fertilizedAny) {\n              if (alreadyFertilizedAny) {\n                setMessage(`此區塊對應的作物今天都已經施過肥了，太肥會死掉，請明天再來！`);\n              } else if (wrongTypeAny) {\n                setMessage(`此區塊沒有適合施打【${fertName}】的作物類型！請確認作物屬性。`);\n              } else {\n                setMessage(\"此區塊目前沒有生長中的作物可以施肥！\");\n              }\n              return prev;\n            }\n            \n            let netBrokeMsg = \"\";\n            const hasMature = targetPlot.slots.some(s => s.crop && s.growth >= s.crop.days);\n            if (hasMature && targetPlot.isNetted) {\n              targetPlot.isNetted = false;\n              netBrokeMsg = \" (作物成熟撐破了防蟲網！)\";\n            }\n\n            setInventory(inv => ({ ...inv, [selectedTool]: Math.max(0, inv[selectedTool] - 1) }));\n            playEffect('water'); \n            setMessage(`✨ 施打${fertName}成功！第 ${plotId + 1} 區對應屬性的作物生長進度縮短了 1 天。${netBrokeMsg}`);\n            \n            // 進階肥料教學完成檢查 (不限順序)\n            if (tutorialStep >= 7 && !flags.tutFert) {\n              setFlags(prev => ({ ...prev, tutFert: true }));\n            }\n          }\n\n          else if (selectedTool === 'seed' && selectedSeed) {\n            const isOccupied = targetPlot.slots.some(s => s.crop !== null);\n            if (isOccupied) {\n              setMessage(\"防呆警告：此區塊尚有植物，請先收成完畢再重新種植！\");\n              return prev;\n            }\n            \n            if (!selectedSeed?.id || (inventory.seeds[selectedSeed.id] || 0) <= 0) {\n              setMessage(\"種子庫存不足！請先去商店購買。\");\n              return prev;\n            }\n            \n            setInventory(inv => ({\n              ...inv,\n              seeds: { ...inv.seeds, [selectedSeed.id]: Math.max(0, inv.seeds[selectedSeed.id] - 1) }\n            }));\n            \n            targetPlot.slots = targetPlot.slots.map(s => ({\n              ...s,\n              crop: selectedSeed,\n              growth: 0,\n              perfectGrowth: true,\n              isWatered: weather === 'rainy' ? true : false, \n              isFertilized: false, \n              hasBug: false,\n              hasWeed: false\n            }));\n            \n            setMessage(`消耗了 1 包 [${selectedSeed.name || '未知'}種子]，在第 ${plotId + 1} 區種滿了！`);\n            playEffect('water');\n            \n            if (inventory.seeds[selectedSeed.id] <= 1) {\n              setSelectedTool('water');\n              setSelectedSeed(null);\n            }\n          } \n\n          return newPlots;\n        });\n      };\n\n      const buyItem = (type, cost) => {\n        if (gold >= cost) {\n          setGold(g => g - cost);\n          if (type === 'net') {\n            setInventory(i => ({ ...i, nets: i.nets + 1 }));\n            setMessage(\"購買防蟲紗網成功！可在農田管理頁面部署。\");\n          } else if (type === 'fert_leaf') {\n            setInventory(i => ({ ...i, fert_leaf: i.fert_leaf + 1 }));\n            setMessage(\"購買氮肥成功！可加速「葉菜類」生長。\");\n          } else if (type === 'fert_root') {\n            setInventory(i => ({ ...i, fert_root: i.fert_root + 1 }));\n            setMessage(\"購買磷肥成功！可加速「根莖類」生長。\");\n          } else if (type === 'fert_fruit') {\n            setInventory(i => ({ ...i, fert_fruit: i.fert_fruit + 1 }));\n            setMessage(\"購買鉀肥成功！可加速「瓜果類」生長。\");\n          } else if (type === 'windbreak') {\n            setInventory(i => ({ ...i, windbreaks: i.windbreaks + 1 }));\n            setMessage(\"購買防風網成功！能抵禦強烈颱風。\");\n          } else if (type === 'scissors') {\n            setInventory(i => ({ ...i, scissors: i.scissors + 10 }));\n            setMessage(\"購買除草剪刀成功！獲得 10 次除草耐用度。\");\n          } else if (type === 'chili') {\n            setInventory(i => ({ ...i, chili: i.chili + 10 }));\n            setMessage(\"購買辣椒水成功！獲得 10 次驅蟲噴灑量。\");\n          }\n        } else {\n          setMessage(\"餘額不足，無法購買這項物品。\");\n        }\n      };\n\n      const sellCrop = (cropId, amount, unitPrice) => {\n        const totalEarn = amount * unitPrice;\n        setGold(g => g + totalEarn);\n        setInventory(inv => ({\n          ...inv,\n          crops: { ...inv.crops, [cropId]: inv.crops[cropId] - amount }\n        }));\n        playEffect('coin');\n        setMessage(`販賣了 ${amount} 份作物，獲得 $${totalEarn.toLocaleString()}！`);\n\n        // 檢查販賣任務 (不限順序)\n        if (tutorialStep >= 7 && !flags.tutSell) {\n          setFlags(prev => ({ ...prev, tutSell: true }));\n        }\n      };\n\n      const buyPlot = (plotId, price) => {\n        if (gold >= price) {\n          setGold(g => g - price);\n          setPlots(prev => prev.map(p => p.id === plotId ? { ...p, isUnlocked: true } : p));\n          setMessage(`🎉 成功解鎖 第 ${plotId + 1} 區農田！農莊規模擴大了！`);\n          playEffect('coin');\n        } else {\n          setMessage(`資金不足！解鎖 第 ${plotId + 1} 區需要 $${price.toLocaleString()}。`);\n        }\n      };\n\n      const applyNet = (plotId) => {\n        const hasMature = plots[plotId].slots.some(s => s.crop && s.growth >= s.crop.days);\n        if (hasMature) {\n          setMessage(\"此區塊已有作物成熟，空間不足以架設防蟲網！\");\n          return;\n        }\n\n        if (inventory.nets > 0 && !plots[plotId].isNetted) {\n          setPlots(prev => prev.map(p => p.id === plotId ? { ...p, isNetted: true } : p));\n          setInventory(inv => ({ ...inv, nets: Math.max(0, inv.nets - 1) }));\n          setMessage(`第 ${plotId + 1} 區已經罩上防蟲紗網，蟲子飛不進來了！`);\n          \n          // 進階防蟲網教學完成檢查 (不限順序)\n          if (tutorialStep >= 7 && !flags.tutNet) {\n            setFlags(prev => ({ ...prev, tutNet: true }));\n          }\n        }\n      };\n\n      const applyWindbreak = (plotId) => {\n        if (inventory.windbreaks > 0 && !plots[plotId].isWindbreaked) {\n          setPlots(prev => prev.map(p => p.id === plotId ? { ...p, isWindbreaked: true } : p));\n          setInventory(inv => ({ ...inv, windbreaks: Math.max(0, inv.windbreaks - 1) }));\n          setMessage(`第 ${plotId + 1} 區已經架設防風網，能抵禦強風侵襲！`);\n        }\n      };\n\n      const handleQuestDeliver = () => {\n        const required = schoolQuest.required;\n        const cropId = schoolQuest.crop.id;\n        const currentAmount = inventory.crops?.[cropId] || 0;\n\n        // 嚴格防呆檢查\n        if (currentAmount < required) {\n            setMessage(`⚠️ 庫存不足！還差 ${required - currentAmount} 個。`);\n            return;\n        }\n        \n        setGold(g => g + (schoolQuest.crop.value * 3 * required));\n        setInventory(inv => ({\n            ...inv,\n            crops: { ...inv.crops, [cropId]: currentAmount - required }\n        }));\n        \n        const seasonRewardMap = { SPRING: 'golden_peach', SUMMER: 'crystal_melon', AUTUMN: 'giant_pumpkin', WINTER: 'white_strawberry' };\n        const rewardId = seasonRewardMap[season];\n        \n        setInventory(inv => ({\n            ...inv,\n            seeds: { ...inv.seeds, [rewardId]: (inv.seeds[rewardId] || 0) + 1 }\n        }));\n        \n        playEffect('coin');\n        setSchoolQuest(null);\n        setShowQuestModal(false);\n        \n        if (!flags.seenQuestReward) {\n            setFlags(f => ({ ...f, seenQuestReward: true }));\n            setEventQueue(q => [...q, { type: 'tutorial_special_seed', crop: CROPS.SPECIAL.find(c=>c.id === rewardId) }]);\n        } else {\n            setMessage(`🎉 委託完成！獲得 3 倍獎金與【傳說種子 x1】！`);\n        }\n      };\n\n      return (\n        <div className={`min-h-screen p-2 md:p-4 font-sans text-slate-800 ${seasonColor} transition-colors duration-1000 select-none relative overflow-x-hidden pb-24`}>\n          \n          <style>{`\n            @keyframes rainFall {\n              0% { transform: translateY(-100%); opacity: 0; }\n              20% { opacity: 1; }\n              80% { opacity: 1; }\n              100% { transform: translateY(300%); opacity: 0; }\n            }\n            .animate-rain { animation: rainFall 0.8s linear infinite; }\n            .rain-delay-1 { animation-delay: 0.2s; }\n            .rain-delay-2 { animation-delay: 0.5s; }\n            .rain-delay-3 { animation-delay: 0.7s; }\n            \n            .hide-scrollbar::-webkit-scrollbar { display: none; }\n            .hide-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }\n          `}</style>\n\n          {/* 飛行作物動畫層 */}\n          {flyingCrops.map(fc => (\n            <FlyingCropComponent key={fc.id} data={fc} onRemove={removeFlyingCrop} />\n          ))}\n\n          {/* --- 新手教學：步驟浮動提示框 (強制隱藏於彈窗開啟時) --- */}\n          {tutorialStep > 1 && !currentEvent && !showModal && !showShop && !showQuestModal && (\n            <div className=\"fixed bottom-8 md:bottom-6 left-0 right-0 z-[40] flex justify-center pointer-events-none px-4\">\n              <div className=\"bg-blue-600 text-white px-3 py-2 md:px-4 md:py-3 rounded-2xl shadow-2xl animate-bounce border-2 border-blue-400 max-w-sm w-full text-center pointer-events-none\">\n                <div className=\"font-black text-sm md:text-base mb-1 text-yellow-300\">\n                  {tutorialStep >= 7 ? `🎓 進階任務 (自由順序)` : `🎓 新手任務 (${tutorialStep - 1}/5)`}\n                </div>\n                <div className=\"text-[10px] md:text-xs font-bold leading-relaxed\">\n                  {tutorialStep === 2 && \"第一步：請點擊右上角的「🛒 商店」，購買一包【地瓜葉】種子！\"}\n                  {tutorialStep === 3 && \"第二步：太棒了！現在請在左側「農具清單」中，點選裝備剛剛購買的【地瓜葉】。\"}\n                  {tutorialStep === 4 && \"第三步：請點擊右側的「第 1 區」農田，進入該區塊，並點擊任何一塊空地將種子種下！\"}\n                  {tutorialStep === 5 && <span>第四步：植物必須<span className=\"text-yellow-300 font-black text-sm md:text-sm mx-1\">【每天】</span>澆水！請裝備左側的「💧 單格澆水」，將<span className=\"underline\">所有剛種下的植物</span>都點擊澆滿水分。</span>}\n                  {tutorialStep === 6 && \"最後一步：完美！確認植物【都有澆水】後，點擊右上角的「🌙 睡覺 ➔」進入下一天！等待它們成熟吧。\"}\n                  {tutorialStep >= 7 && (\n                    <div className=\"flex flex-col gap-1.5 text-left bg-blue-700/50 p-2 rounded-xl mt-1.5\">\n                      <p className=\"text-yellow-100\">請完成以下三項進階農務（不限順序）：</p>\n                      <label className={`flex items-start gap-1.5 ${flags.tutSell ? 'opacity-50 line-through text-yellow-300' : ''}`}>\n                        <span>{flags.tutSell ? '✅' : '🔲'}</span> <span>去「🛒 商店」賣出剛收成的作物。</span>\n                      </label>\n                      <label className={`flex items-start gap-1.5 ${flags.tutFert ? 'opacity-50 line-through text-yellow-300' : ''}`}>\n                        <span>{flags.tutFert ? '✅' : '🔲'}</span> <span>裝備【🧪 氮肥(葉菜)】並對地瓜葉施肥。</span>\n                      </label>\n                      <label className={`flex items-start gap-1.5 ${flags.tutNet ? 'opacity-50 line-through text-yellow-300' : ''}`}>\n                        <span>{flags.tutNet ? '✅' : '🔲'}</span> <span>點擊進入農田區塊，部署【防蟲網】。</span>\n                      </label>\n                    </div>\n                  )}\n                </div>\n              </div>\n            </div>\n          )}\n\n          {/* --- 開場畫面 / 觸發新手教學 --- */}\n          {!isGameStarted && (\n            <div className=\"fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center p-4 z-[100] overflow-y-auto hide-scrollbar\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2.5rem] max-w-2xl w-full shadow-2xl animate-in zoom-in duration-500 my-auto\">\n                <h1 className=\"text-3xl md:text-4xl font-black text-center mb-6 text-emerald-700\">🌾 四季農莊：島嶼物語</h1>\n                \n                <div className=\"space-y-4 text-slate-700 font-bold text-sm bg-emerald-50 p-4 md:p-6 rounded-3xl mb-6 border-2 border-emerald-100 max-h-[40vh] overflow-y-auto hide-scrollbar\">\n                  <p className=\"text-sm md:text-base text-emerald-800\">歡迎來到台灣專屬的農業經營模擬器！在這裡，你將體驗為期 365 天的農夫生活：</p>\n                  <ul className=\"space-y-3 mt-4 text-xs md:text-sm\">\n                    <li className=\"flex items-start gap-2\"><span className=\"text-xl\">🌦️</span> <span><strong className=\"text-blue-700\">四季變化與天氣</strong>：春雨、梅雨、秋颱、冬旱。雨天免澆水，但要提防颱風摧毀心血！</span></li>\n                    <li className=\"flex items-start gap-2\"><span className=\"text-xl\">🥭</span> <span><strong className=\"text-green-700\">台灣在地蔬果</strong>：種植大甲芋頭、愛文芒果等 12 種在地作物，體驗真實生長週期。</span></li>\n                    <li className=\"flex items-start gap-2\"><span className=\"text-xl\">🏫</span> <span><strong className=\"text-amber-700\">小鎮特殊委託</strong>：接取校長的委託，學習市場「供需法則」賺取 3 倍利潤。</span></li>\n                    <li className=\"flex items-start gap-2\"><span className=\"text-xl\">🛡️</span> <span><strong className=\"text-purple-700\">防災與生態管理</strong>：架設防蟲紗網與防風網，學習農業風險管理。</span></li>\n                  </ul>\n                </div>\n\n                <div className=\"mb-6\">\n                  <label className=\"block text-xs font-black text-slate-400 uppercase tracking-widest mb-3 text-center\">\n                    請為你的農莊取個響亮的名字 (最多 8 個字)\n                  </label>\n                  <input\n                    type=\"text\"\n                    maxLength={8}\n                    placeholder=\"例如：開心農莊\"\n                    value={farmName}\n                    onChange={(e) => setFarmName(e.target.value)}\n                    className=\"w-full text-xl md:text-2xl font-black text-center text-slate-800 p-3 md:p-4 rounded-2xl border-4 border-slate-200 focus:border-emerald-500 focus:outline-none transition-colors\"\n                  />\n                </div>\n\n                <div className=\"flex flex-col gap-3 md:gap-4\">\n                  <button\n                    onClick={() => {\n                      if (!farmName.trim()) setFarmName('開心農莊');\n                      setIsGameStarted(true);\n                      setTutorialStep(1); \n                    }}\n                    className=\"w-full bg-emerald-600 text-white py-4 md:py-5 rounded-2xl font-black text-lg md:text-xl tracking-widest hover:bg-emerald-700 active:scale-95 transition-all shadow-lg hover:shadow-emerald-600/50\"\n                  >\n                    開始新經營！\n                  </button>\n                  \n                  {saveExists && (\n                    <button\n                      onClick={handleLoad}\n                      className=\"w-full bg-indigo-100 text-indigo-700 py-3 md:py-4 rounded-2xl font-black text-lg md:text-xl tracking-widest hover:bg-indigo-200 active:scale-95 transition-all shadow-md\"\n                    >\n                      📂 繼續上次的進度\n                    </button>\n                  )}\n                </div>\n              </div>\n            </div>\n          )}\n\n          {/* 新手教學 Step 1 彈窗 */}\n          {tutorialStep === 1 && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[110]\">\n              <div className=\"bg-white p-8 rounded-[2.5rem] max-w-md w-full text-center shadow-2xl animate-in zoom-in duration-300\">\n                <div className=\"text-6xl mb-4\">👨‍🌾</div>\n                <h2 className=\"text-2xl font-black mb-4 text-emerald-800\">歡迎來到四季農莊！</h2>\n                <p className=\"text-slate-600 font-bold text-sm mb-8 leading-relaxed\">\n                  看起來你是剛來到這座島嶼的新手農夫呢。<br/>不用擔心，我會一步一步教你如何種出第一批作物！<br/><br/>準備好開始你的農業生活了嗎？\n                </p>\n                <div className=\"flex flex-col gap-3\">\n                  <button onClick={() => setTutorialStep(2)} className=\"w-full bg-emerald-600 text-white py-4 rounded-2xl font-black text-lg hover:bg-emerald-700 transition-colors shadow-md\">\n                    開始新手教學！\n                  </button>\n                  <button onClick={() => setTutorialStep(0)} className=\"w-full bg-slate-100 text-slate-500 py-3 rounded-2xl font-bold text-sm hover:bg-slate-200 transition-colors\">\n                    我已經是老手了，跳過教學\n                  </button>\n                </div>\n              </div>\n            </div>\n          )}\n\n          {/* RWD 頂部資訊欄 */}\n          <div className=\"max-w-4xl mx-auto bg-white/80 backdrop-blur rounded-3xl p-4 md:p-6 shadow-xl mb-4 md:mb-6 flex flex-col md:flex-row gap-4 justify-between items-center border border-white/50 relative z-40\">\n            \n            <div className=\"flex gap-4 items-center w-full md:w-auto justify-between md:justify-start\">\n              <div className=\"bg-slate-800 text-white p-2 md:p-3 rounded-2xl text-center min-w-[70px] md:min-w-[80px]\">\n                <div className=\"text-[9px] md:text-[10px] uppercase opacity-60\">天數</div>\n                <div className=\"text-lg md:text-xl font-black\">{day}</div>\n              </div>\n              <div>\n                <div className=\"text-[10px] md:text-xs font-bold text-slate-400 uppercase tracking-tighter\">當前天氣</div>\n                <div className=\"text-xl md:text-2xl font-black flex items-center gap-2\">\n                  <span className=\"text-3xl md:text-4xl cursor-help hover:scale-110 transition-transform\" title={`${seasonName}季 - ${weather === 'typhoon' ? '狂風暴雨' : weather === 'rainy' ? '今日雨天免澆水' : '晴空萬里'}`}>\n                    {weather === 'typhoon' ? '🌀' : weather === 'rainy' ? '🌧️' : '☀️'}\n                  </span>\n                </div>\n              </div>\n            </div>\n            \n            <div className=\"flex flex-wrap items-center justify-center gap-2 md:gap-4 w-full md:w-auto\">\n              {schoolQuest && (\n                <button \n                  onClick={() => setShowQuestModal(true)}\n                  className=\"bg-gradient-to-r from-yellow-300 to-amber-500 text-yellow-900 px-3 md:px-5 py-1.5 md:py-2 rounded-xl md:rounded-2xl border-2 border-yellow-200 shadow-md font-black hover:scale-105 active:scale-95 transition-all flex flex-col items-center justify-center animate-bounce\"\n                >\n                  <span className=\"text-[9px] md:text-[10px] leading-none mb-0.5 font-black text-red-600 tracking-tighter bg-yellow-100/50 px-1 rounded\">倒數 {schoolQuest.daysLeft} 天</span>\n                  <span className=\"flex items-center gap-1 text-xs md:text-sm leading-none mt-0.5\">🏫 委託交付</span>\n                </button>\n              )}\n\n              <div className=\"bg-emerald-600/10 px-3 md:px-5 py-1.5 md:py-2 rounded-xl md:rounded-2xl border-2 border-emerald-600/20\">\n                <div className=\"text-[8px] md:text-[10px] font-bold text-emerald-800 uppercase text-center\">農莊名稱</div>\n                <div className=\"text-sm md:text-lg font-black text-emerald-700\">{farmName || '農莊'}</div>\n              </div>\n\n              <div className=\"bg-yellow-400/20 px-3 md:px-5 py-1.5 md:py-2 rounded-xl md:rounded-2xl border-2 border-yellow-400/50\">\n                <div className=\"text-[8px] md:text-[10px] font-bold text-yellow-700 uppercase text-center\">資金餘額</div>\n                <div className=\"text-lg md:text-2xl font-mono font-black text-yellow-600\">${gold.toLocaleString()}</div>\n              </div>\n\n              <button \n                onClick={() => setShowShop(true)}\n                className={`bg-gradient-to-r from-green-400 to-emerald-600 text-white px-3 md:px-6 py-2 md:py-3 rounded-xl font-black hover:shadow-xl active:scale-95 transition-all flex items-center gap-1 md:gap-2 shadow-md ${tutorialStep === 2 || (tutorialStep >= 7 && !flags.tutSell) ? 'ring-4 ring-blue-500 animate-pulse' : ''}`}\n              >\n                <span className=\"text-base md:text-lg\">🛒</span> <span className=\"text-xs md:text-base\">商店</span>\n              </button>\n              \n              <button \n                onClick={() => {\n                  // 強制防呆：有教學任務進行時無法點擊睡覺\n                  if (tutorialStep > 0 && tutorialStep !== 6) {\n                    setMessage(\"⚠️ 請先完成畫面下方的「新手教學」步驟，才能結束這一天喔！\");\n                    return;\n                  }\n                  setShowModal('sleep');\n                }} \n                className={`bg-slate-800 text-white px-3 md:px-6 py-2 md:py-3 rounded-xl font-bold hover:bg-slate-700 active:scale-95 transition-all shadow-md flex items-center gap-1 md:gap-2 ${tutorialStep === 6 ? 'ring-4 ring-blue-500 animate-pulse' : ''}`}\n              >\n                🌙 <span className=\"text-xs md:text-base\">睡覺 ➔</span>\n              </button>\n            </div>\n          </div>\n\n          <div className=\"max-w-4xl mx-auto grid grid-cols-1 md:grid-cols-4 gap-4 md:gap-6 relative z-30\">\n            \n            {/* 左側：收成箱與農具清單 */}\n            <div className=\"md:col-span-1 flex flex-col h-auto md:h-[450px] gap-4 relative z-40\">\n              \n              <div className=\"relative min-h-[90px] md:min-h-[110px]\">\n                <div \n                    ref={dropZoneRef}\n                    className={`absolute inset-0 bg-white/80 border-4 border-dashed rounded-[1.5rem] md:rounded-[2rem] p-2 md:p-3 flex flex-col items-center justify-center border-slate-300 shadow-sm transition-all duration-300`}\n                >\n                    <div className=\"text-3xl md:text-4xl mb-1\">📥</div>\n                    <div className=\"font-black text-slate-700 text-sm md:text-base\">收成箱</div>\n                    <div className=\"font-bold mt-1 px-3 py-1 rounded-full text-[9px] md:text-[10px] bg-slate-100 text-slate-500\">\n                        點擊作物自動收成\n                    </div>\n                </div>\n              </div>\n\n              <div className={`bg-white/80 p-3 md:p-4 rounded-[2rem] shadow-sm border flex flex-col flex-1 overflow-hidden min-h-[180px] md:min-h-0 ${tutorialStep === 3 || tutorialStep === 5 ? 'border-4 border-blue-500 shadow-[0_0_20px_rgba(59,130,246,0.5)]' : 'border-white'}`}>\n                <h3 className=\"text-[10px] font-black mb-2 md:mb-3 text-slate-400 uppercase tracking-widest shrink-0\">農具與庫存清單</h3>\n                <div className=\"grid grid-cols-4 md:grid-cols-2 gap-3 overflow-y-auto p-2 hide-scrollbar flex-1 content-start\">\n                  {[\n                    { id: 'water', label: day >= 20 ? '全區灑水' : '單格澆水', icon: '💧' },\n                    { id: 'chili', label: '辣椒水', icon: '🌶️', count: inventory.chili },\n                    { id: 'weed', label: '除草剪刀', icon: '✂️', count: inventory.scissors },\n                    ...(inventory.fert_leaf > 0 ? [{ id: 'fert_leaf', label: '氮肥(葉菜)', icon: <FertilizerBag type=\"leaf\" />, count: inventory.fert_leaf }] : []),\n                    ...(inventory.fert_root > 0 ? [{ id: 'fert_root', label: '磷肥(根莖)', icon: <FertilizerBag type=\"root\" />, count: inventory.fert_root }] : []),\n                    ...(inventory.fert_fruit > 0 ? [{ id: 'fert_fruit', label: '鉀肥(瓜果)', icon: <FertilizerBag type=\"fruit\" />, count: inventory.fert_fruit }] : []),\n                    ...Object.keys(inventory.seeds || {})\n                      .filter(id => inventory.seeds[id] > 0)\n                      .map(id => {\n                        const crop = Object.values(CROPS).flat().find(c => c?.id === id);\n                        if (!crop) return null;\n                        return {\n                          id: `seed_${id}`,\n                          type: 'seed',\n                          cropData: crop,\n                          label: `${crop.name}種子`, \n                          icon: <SeedBag crop={crop} />,\n                          count: inventory.seeds[id]\n                        };\n                      })\n                      .filter(Boolean)\n                  ].map(tool => {\n                    if (!tool) return null;\n                    const isSelected = tool.type === 'seed' \n                      ? (selectedTool === 'seed' && selectedSeed?.id === tool.cropData?.id)\n                      : selectedTool === tool.id;\n\n                    const isHighlight = (tutorialStep === 3 && tool.type === 'seed' && tool.cropData.id === 'sweetpotatoleaf') || \n                                        (tutorialStep === 5 && tool.id === 'water') ||\n                                        (tutorialStep >= 7 && !flags.tutFert && tool.id === 'fert_leaf');\n\n                    return (\n                      <button\n                        key={tool.id}\n                        onClick={() => {\n                          if (tool.type === 'seed') {\n                            setSelectedTool('seed');\n                            setSelectedSeed(tool.cropData);\n                          } else {\n                            setSelectedTool(tool.id);\n                            setSelectedSeed(null); \n                          }\n                        }}\n                        className={`p-2 md:p-3 rounded-xl md:rounded-2xl border-2 transition-all flex flex-col items-center justify-center group relative ${isSelected ? 'border-blue-500 bg-white shadow-md scale-105 z-10' : 'border-transparent bg-white/40 hover:bg-white'} ${isHighlight ? 'ring-4 ring-yellow-400 animate-pulse' : ''}`}\n                      >\n                        <span className=\"text-xl md:text-2xl group-active:scale-125 transition-transform flex items-center justify-center h-10 w-10\">{tool.icon}</span>\n                        <span className=\"text-[8px] md:text-[10px] font-black mt-1 uppercase text-center w-full truncate\">{tool.label}</span>\n                        {tool.count !== undefined && (\n                          <span className={`absolute -top-1.5 -right-1.5 md:-top-2 md:-right-2 text-[9px] md:text-[11px] font-bold text-white px-1.5 py-0.5 rounded-full shadow-md z-20 ${tool.count > 0 ? 'bg-blue-500' : 'bg-slate-400'}`}>\n                            {tool.count}\n                          </span>\n                        )}\n                      </button>\n                    );\n                  })}\n                </div>\n              </div>\n            </div>\n\n            {/* 農田主畫面 (8格) */}\n            <div className=\"md:col-span-3\">\n              {activePlot === null ? (\n                <div className=\"grid grid-cols-2 gap-3 md:gap-4 h-[350px] md:h-[450px]\">\n                  {plots.map(plot => {\n                    if (!plot) return null;\n                    \n                    if (!plot.isUnlocked) {\n                      const price = PLOT_PRICES[plot.id];\n                      return (\n                        <div \n                          key={plot.id}\n                          onClick={() => buyPlot(plot.id, price)}\n                          className=\"bg-slate-200/60 border-4 border-dashed border-slate-400 rounded-[1.5rem] md:rounded-[2rem] flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50 transition-all shadow-inner group\"\n                        >\n                          <div className=\"text-4xl md:text-5xl mb-2 opacity-40 group-hover:scale-110 transition-transform\">🔒</div>\n                          <div className=\"text-[10px] md:text-sm font-black text-slate-500 uppercase tracking-widest\">第 {plot.id + 1} 區 (未開放)</div>\n                          <div className=\"mt-3 bg-blue-100 text-blue-700 px-3 md:px-4 py-1.5 md:py-2 rounded-xl font-black text-[10px] md:text-sm border-2 border-blue-200 transition-colors group-hover:bg-blue-600 group-hover:text-white\">\n                            解鎖 $ {price.toLocaleString()}\n                          </div>\n                        </div>\n                      );\n                    }\n\n                    const plantedCount = plot.slots.filter(s => s?.crop).length;\n                    const matureCount = plot.slots.filter(s => s?.crop && s.growth >= s.crop.days).length;\n                    const wateredCount = plot.slots.filter(s => s?.crop && s.isWatered).length;\n                    const unhandledAlert = plot.slots.some(s => s?.hasBug || s?.hasWeed);\n                    \n                    const borderColor = unhandledAlert ? 'border-red-500' : (weather === 'rainy' ? 'border-blue-400 shadow-[0_0_15px_rgba(96,165,250,0.5)]' : 'border-white');\n                    const isGiantPumpkin = plot.slots[0]?.crop?.id === 'giant_pumpkin';\n                    const isHighlight = tutorialStep === 4 && plot.id === 0;\n\n                    return (\n                      <div \n                        key={plot.id}\n                        onClick={() => setActivePlot(plot.id)}\n                        className={`bg-amber-900/10 border-4 rounded-[1.5rem] md:rounded-[2rem] relative overflow-hidden cursor-pointer hover:border-amber-500 transition-all flex flex-col items-center justify-center group shadow-inner ${borderColor} ${isHighlight ? 'ring-4 ring-blue-500 animate-pulse' : ''}`}\n                      >\n                        {weather === 'rainy' && (\n                          <div className=\"absolute inset-0 pointer-events-none overflow-hidden bg-blue-500/10 flex justify-evenly opacity-50 z-10\">\n                            <div className=\"w-[1px] md:w-[2px] h-8 md:h-12 bg-blue-300 animate-rain\"></div>\n                            <div className=\"w-[1px] md:w-[2px] h-6 md:h-8 bg-blue-300 animate-rain rain-delay-1 mt-4\"></div>\n                            <div className=\"w-[1px] md:w-[2px] h-10 md:h-16 bg-blue-300 animate-rain rain-delay-2 mt-8\"></div>\n                            <div className=\"w-[1px] md:w-[2px] h-8 md:h-10 bg-blue-300 animate-rain rain-delay-3 mt-2\"></div>\n                          </div>\n                        )}\n\n                        <div className=\"absolute top-2 left-2 md:top-4 md:left-4 text-[8px] md:text-[10px] font-black bg-amber-900/20 px-2 py-1 md:px-3 md:py-1 rounded-full uppercase z-20\">第 {plot.id + 1} 區</div>\n                        {plot.isNetted && <div className=\"absolute inset-0 bg-blue-400/10 border-2 border-dashed border-blue-400/50 rounded-[1.3rem] md:rounded-[1.8rem] pointer-events-none z-20\"></div>}\n                        {plot.isWindbreaked && <div className=\"absolute inset-0 border-4 border-emerald-600/60 rounded-[1.3rem] md:rounded-[1.8rem] pointer-events-none z-20\"></div>}\n                        \n                        <div className={`text-4xl md:text-5xl group-hover:scale-110 transition-transform z-20 ${isGiantPumpkin && matureCount === plantedCount ? 'animate-pulse' : ''}`}>\n                          {plantedCount > 0 ? (\n                            isGiantPumpkin ? '🎃' : (matureCount === plantedCount ? '✨' : '🌿')\n                          ) : '🕳️'}\n                        </div>\n                        <div className=\"mt-2 md:mt-4 flex flex-col items-center gap-1 z-20\">\n                          <div className=\"text-[8px] md:text-[10px] font-black uppercase text-amber-900/60 bg-white/40 px-2 py-0.5 rounded-full\">\n                            {plantedCount > 0 ? (isGiantPumpkin ? '巨型作物生長中' : `${plantedCount}/8 正在生長`) : '空置農田'}\n                          </div>\n                          {plantedCount > 0 && (\n                            <div className={`text-[8px] md:text-[10px] font-black px-1.5 py-0.5 md:px-2 md:py-1 rounded ${wateredCount < plantedCount ? 'bg-amber-200 text-amber-700' : 'bg-blue-100 text-blue-600'}`}>\n                              💧 澆水: {wateredCount}/{plantedCount}\n                            </div>\n                          )}\n                          {unhandledAlert && (\n                            <div className=\"text-[8px] md:text-[10px] font-black bg-red-100 text-red-600 px-1.5 py-0.5 md:px-2 md:py-0.5 rounded animate-pulse shadow-sm\">\n                              ⚠️ 發現蟲草\n                            </div>\n                          )}\n                        </div>\n                      </div>\n                    );\n                  })}\n                </div>\n              ) : (\n                <div className=\"bg-white/80 p-4 md:p-8 rounded-[1.5rem] md:rounded-[2.5rem] shadow-2xl border border-white animate-in zoom-in duration-300 relative overflow-hidden flex flex-col h-full md:h-[450px]\">\n                  \n                  {weather === 'rainy' && (\n                    <div className=\"absolute inset-0 pointer-events-none overflow-hidden bg-blue-500/5 flex justify-evenly opacity-40 z-0\">\n                      <div className=\"w-[1px] md:w-[2px] h-12 md:h-20 bg-blue-400 animate-rain\"></div>\n                      <div className=\"w-[1px] md:w-[2px] h-10 md:h-16 bg-blue-400 animate-rain rain-delay-1 mt-10\"></div>\n                      <div className=\"w-[1px] md:w-[2px] h-16 md:h-24 bg-blue-400 animate-rain rain-delay-2 mt-20\"></div>\n                      <div className=\"w-[1px] md:w-[2px] h-8 md:h-12 bg-blue-400 animate-rain rain-delay-3 mt-5\"></div>\n                      <div className=\"w-[1px] md:w-[2px] h-12 md:h-18 bg-blue-400 animate-rain rain-delay-1 mt-30\"></div>\n                    </div>\n                  )}\n\n                  <div className=\"flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 md:mb-6 gap-3 relative z-10 shrink-0\">\n                    <button onClick={() => setActivePlot(null)} className=\"bg-slate-100 hover:bg-slate-200 px-3 md:px-4 py-1.5 md:py-2 rounded-xl text-[10px] md:text-xs font-black transition-colors shrink-0\">❮ 前往其他農地</button>\n                    <div className=\"flex items-center gap-2 flex-wrap justify-start sm:justify-end w-full sm:w-auto\">\n                      <span className=\"font-black text-slate-400 uppercase text-[10px] md:text-xs tracking-widest mr-1 md:mr-2\">第 {activePlot + 1} 區管理中</span>\n                      \n                      {inventory.nets > 0 && !plots[activePlot].isNetted && (\n                        <button onClick={() => applyNet(activePlot)} className={`bg-blue-600 text-white text-[9px] md:text-[10px] px-2 py-1.5 md:px-3 md:py-2 rounded-lg md:rounded-xl font-black hover:bg-blue-700 transition-all ${(tutorialStep >= 7 && !flags.tutNet) ? 'ring-4 ring-yellow-400 animate-pulse' : ''}`}>部署防蟲網</button>\n                      )}\n                      {plots[activePlot].isNetted && <span className=\"bg-blue-100 text-blue-600 text-[9px] md:text-[10px] px-2 py-1.5 md:px-2 md:py-2 rounded-lg md:rounded-xl font-black\">防蟲中 🕸️</span>}\n                      \n                      {inventory.windbreaks > 0 && !plots[activePlot].isWindbreaked && (\n                        <button onClick={() => applyWindbreak(activePlot)} className=\"bg-emerald-600 text-white text-[9px] md:text-[10px] px-2 py-1.5 md:px-3 md:py-2 rounded-lg md:rounded-xl font-black hover:bg-emerald-700 transition-all\">架設防風網</button>\n                      )}\n                      {plots[activePlot].isWindbreaked && <span className=\"bg-emerald-100 text-emerald-700 text-[9px] md:text-[10px] px-2 py-1.5 md:px-2 md:py-2 rounded-lg md:rounded-xl font-black\">防風中 🛡️</span>}\n                    </div>\n                  </div>\n\n                  {plots[activePlot].slots[0]?.crop?.id === 'giant_pumpkin' ? (\n                    <div className=\"flex-1 w-full relative z-10 flex flex-col\">\n                      <div\n                        onClick={(e) => {\n                           if (plots[activePlot].slots[0].crop && plots[activePlot].slots[0].growth >= plots[activePlot].slots[0].crop.days) {\n                              handleHarvestClick(e, activePlot, 0, plots[activePlot].slots[0].crop, true);\n                           } else {\n                              handleSlotClick(activePlot, 0);\n                           }\n                        }}\n                        className={`flex-1 w-full rounded-xl md:rounded-[2rem] border-4 flex flex-col items-center justify-center relative transition-all active:scale-[0.98] cursor-pointer overflow-hidden ${\n                          plots[activePlot].slots[0].isWatered \n                            ? 'bg-amber-800 border-amber-950 shadow-[inset_0_10px_30px_rgba(0,0,0,0.6)]' \n                            : 'bg-amber-100 border-amber-300'\n                        }`}\n                      >\n                        {plots[activePlot].slots[0].isFertilized && (\n                          <div className=\"absolute top-3 left-3 md:top-6 md:left-6 bg-purple-100 border-2 border-purple-300 text-purple-700 text-xs md:text-sm px-3 py-1.5 rounded-lg shadow-sm font-black z-20 flex items-center gap-1 animate-in zoom-in\">\n                            <span className=\"text-lg md:text-xl\">🧪</span><span>已施打神級肥料</span>\n                          </div>\n                        )}\n\n                        {(plots[activePlot].slots.some(s => s.hasBug || s.hasWeed)) && (\n                          <div className=\"absolute top-3 right-3 md:top-6 md:right-6 flex flex-col gap-2 z-20 bg-white/30 p-2 rounded-2xl backdrop-blur-sm\">\n                            {plots[activePlot].slots.some(s => s.hasBug) && <span className=\"animate-bounce text-3xl md:text-5xl drop-shadow-md\">🐛</span>}\n                            {plots[activePlot].slots.some(s => s.hasWeed) && <span className=\"animate-pulse w-8 h-8 md:w-12 md:h-12 drop-shadow-md inline-block\"><WeedIcon className=\"w-full h-full\" /></span>}\n                          </div>\n                        )}\n\n                        <span \n                          className={`transition-all duration-1000 z-10 ${plots[activePlot].slots[0].growth >= plots[activePlot].slots[0].crop.days ? 'drop-shadow-[0_20px_30px_rgba(0,0,0,0.5)] animate-pulse' : 'opacity-90 drop-shadow-lg'}`}\n                          style={{\n                            fontSize: `${6 + (plots[activePlot].slots[0].growth / plots[activePlot].slots[0].crop.days) * 12}rem`,\n                            lineHeight: 1\n                          }}\n                        >\n                          🎃\n                        </span>\n\n                        <div className=\"absolute bottom-6 md:bottom-10 w-3/4 h-3 md:h-4 bg-slate-900/50 rounded-full overflow-hidden border-2 border-slate-900/60 z-20 backdrop-blur-sm\">\n                          <div className=\"h-full bg-gradient-to-r from-green-400 to-emerald-500 transition-all shadow-[inset_0_2px_4px_rgba(255,255,255,0.4)]\" style={{ width: `${Math.min(100, (plots[activePlot].slots[0].growth / plots[activePlot].slots[0].crop.days) * 100)}%` }} />\n                        </div>\n                        \n                        {!plots[activePlot].slots[0].isWatered && (\n                          <div className=\"absolute bottom-2 md:bottom-4 text-xs md:text-sm font-black text-amber-300 uppercase tracking-widest z-20 animate-pulse bg-slate-900/50 px-3 py-1 rounded-full\">\n                            極度缺水，請立即灌溉\n                          </div>\n                        )}\n                      </div>\n                    </div>\n                  ) : (\n                    <div className=\"grid grid-cols-4 gap-2 md:gap-4 relative z-10 flex-1 content-start overflow-y-auto pr-1 custom-scrollbar\">\n                      {plots[activePlot].slots.map(slot => (\n                        <div \n                          key={slot.id}\n                          onClick={(e) => {\n                             if (slot.crop && slot.growth >= slot.crop.days) {\n                                 handleHarvestClick(e, activePlot, slot.id, slot.crop, false);\n                             } else {\n                                 handleSlotClick(activePlot, slot.id);\n                             }\n                          }}\n                          className={`aspect-square rounded-xl md:rounded-[1.5rem] border-2 md:border-4 flex flex-col items-center justify-center relative transition-all active:scale-95 cursor-pointer ${\n                            slot.isWatered \n                              ? 'bg-amber-800 border-amber-950 shadow-[inset_0_5px_10px_rgba(0,0,0,0.5)] md:shadow-[inset_0_10px_20px_rgba(0,0,0,0.5)]' \n                              : 'bg-amber-100 border-amber-300'\n                          }`}\n                        >\n                          {slot.isFertilized && (\n                            <div className=\"absolute top-1 left-1 md:top-2 md:left-2 bg-purple-100 border border-purple-300 text-purple-700 text-[8px] md:text-[10px] px-1 rounded shadow-sm font-black z-20 flex items-center gap-0.5 animate-in zoom-in\">\n                              <span>🧪</span><span className=\"hidden md:inline\">已施肥</span>\n                            </div>\n                          )}\n\n                          {slot.crop ? (\n                            <>\n                              <span className={`text-4xl md:text-6xl transition-all ${slot.growth >= slot.crop.days ? 'scale-110 drop-shadow-md' : 'scale-50 opacity-40'}`}>\n                                {slot.growth >= slot.crop.days ? slot.crop.icon : '🌱'}\n                              </span>\n                              <div className=\"absolute bottom-1 md:bottom-2 w-6 md:w-10 h-1 md:h-1 bg-slate-200/50 rounded-full overflow-hidden\">\n                                <div className=\"h-full bg-green-400 transition-all\" style={{ width: `${Math.min(100, (slot.growth / slot.crop.days) * 100)}%` }} />\n                              </div>\n                            </>\n                          ) : (\n                            <span className={`${slot.isWatered ? 'text-amber-600/60' : 'text-amber-400/80'} text-[8px] md:text-[9px] font-black uppercase tracking-tighter`}>可種植</span>\n                          )}\n                          \n                          {(!slot.crop || slot.growth < slot.crop.days) && (\n                            <div className=\"absolute top-1 right-1 md:top-2 md:right-2 flex flex-col gap-0.5 md:gap-1 items-center pointer-events-none\">\n                              {slot.hasBug && <span className=\"animate-bounce text-[14px] md:text-lg drop-shadow-md\">🐛</span>}\n                              {slot.hasWeed && <span className=\"animate-pulse w-[14px] md:w-[18px] h-[14px] md:h-[18px] drop-shadow-md\"><WeedIcon className=\"w-full h-full\" /></span>}\n                            </div>\n                          )}\n                        </div>\n                      ))}\n                    </div>\n                  )}\n                </div>\n              )}\n            </div>\n          </div>\n\n          <div className=\"max-w-4xl mx-auto mt-4 md:mt-6 bg-slate-800 text-white px-4 py-3 md:px-6 md:py-4 rounded-xl md:rounded-2xl shadow-2xl flex items-center gap-3 md:gap-4 animate-in slide-in-from-bottom duration-500 relative z-30\">\n            <div className=\"text-xl md:text-2xl shrink-0\">💡</div>\n            <div className=\"text-[10px] md:text-xs font-bold leading-relaxed whitespace-pre-line\">{String(message)}</div>\n          </div>\n\n          {/* --- 初見教學與觸發事件 --- */}\n\n          {/* 第一次忘記澆水 */}\n          {currentEvent?.type === 'tutorial_forgot_water' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[100]\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar border-4 border-amber-500\">\n                <div className=\"text-center font-black text-amber-600 mb-2 animate-pulse\">⚠️ 農業警報</div>\n                <div className=\"text-5xl md:text-6xl mb-4 text-center\">🥀</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-amber-900\">糟糕！忘記澆水了！</h2>\n                <div className=\"bg-amber-50 p-4 rounded-xl md:rounded-2xl mb-6 mt-4\">\n                  <p className=\"text-slate-700 text-[10px] md:text-xs leading-relaxed font-bold\">\n                    你昨天似乎忘記幫田裡的某些作物澆水了...\n                  </p>\n                  <p className=\"text-slate-800 text-[10px] md:text-xs leading-relaxed font-black mt-3 bg-amber-200 p-3 rounded-xl border border-amber-300 shadow-inner\">\n                    💡 後果提醒：<br/>\n                    1. 缺乏水分的作物，昨晚的<span className=\"text-red-600\">生長進度已經完全停滯</span>。<br/>\n                    2. 缺水的作物將<span className=\"text-red-600\">永遠失去</span>獲得「完美收成勳章」的資格。<br/>\n                    請務必記得每天都要檢查水分喔！（雨天除外）\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-amber-500 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-amber-600 transition-colors\">\n                  我知道了，以後會注意！\n                </button>\n              </div>\n            </div>\n          )}\n\n          {/* 颱風災損事件 */}\n          {currentEvent?.type === 'typhoon_damage' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[100]\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar border-4 border-blue-600\">\n                <div className=\"text-center font-black text-blue-600 mb-2 animate-pulse\">⚠️ 災情回報</div>\n                <div className=\"text-5xl md:text-6xl mb-4 text-center\">🌪️</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-slate-800\">颱風過境，滿目瘡痍！</h2>\n                <div className=\"bg-slate-100 p-4 rounded-xl md:rounded-2xl mb-6 mt-4\">\n                  <p className=\"text-slate-700 text-[10px] md:text-xs leading-relaxed font-bold\">\n                    昨晚的狂風暴雨無情地摧毀了農田裡缺乏保護的作物...\n                  </p>\n                  <p className=\"text-red-600 text-[10px] md:text-xs leading-relaxed font-black mt-3 bg-red-100 p-3 rounded-xl border border-red-200\">\n                    統計損失：共有 {currentEvent.count} 株作物被強風連根拔起！\n                  </p>\n                  <p className=\"text-slate-600 text-[10px] md:text-xs leading-relaxed font-bold mt-3\">\n                    💡 記得在颱風來臨前，提前購買並部署【防風網】來保護心血喔！\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-blue-600 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-blue-700 transition-colors\">\n                  我知道了，只能重新振作了\n                </button>\n              </div>\n            </div>\n          )}\n\n          {/* 作物死亡事件 */}\n          {currentEvent?.type === 'crop_died' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[100]\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar border-4 border-slate-600\">\n                <div className=\"text-center font-black text-slate-500 mb-2 animate-pulse\">⚠️ 悲報</div>\n                <div className=\"text-5xl md:text-6xl mb-4 text-center\">🪦</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-slate-800\">作物枯死了！</h2>\n                <div className=\"bg-slate-100 p-4 rounded-xl md:rounded-2xl mb-6 mt-4\">\n                  <p className=\"text-slate-700 text-[10px] md:text-xs leading-relaxed font-bold\">\n                    你農田裡有作物因為<span className=\"text-red-600 font-black\">【未處理蟲害】</span>或<span className=\"text-green-700 font-black\">【雜草搶奪養分】</span>而在昨晚枯死了！\n                  </p>\n                  <p className=\"text-slate-600 text-[10px] md:text-xs leading-relaxed font-bold mt-3\">\n                    💡 請務必每天檢查農田狀態，及時進行除草和驅蟲，否則心血都會白費喔！\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-slate-600 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-slate-700 transition-colors\">\n                  我知道了，真是太可惜了\n                </button>\n              </div>\n            </div>\n          )}\n\n          {currentEvent?.type === 'tutorial_day2_water' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[100]\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar border-4 border-blue-400\">\n                <div className=\"text-center font-black text-blue-600 mb-2 animate-pulse\">🎓 新手必讀</div>\n                <div className=\"text-5xl md:text-6xl mb-4 text-center\">💧</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-blue-900\">新的一天：記得澆水！</h2>\n                <div className=\"bg-blue-50 p-4 rounded-xl md:rounded-2xl mb-6 mt-4\">\n                  <p className=\"text-slate-700 text-[10px] md:text-xs leading-relaxed font-bold\">\n                    早安！在《四季農莊》中，想要植物順利長大，最重要的鐵則就是：<br/><br/>\n                    <span className=\"text-blue-600 font-black text-sm md:text-base bg-blue-200 px-2 py-1 rounded\">【每天都必須幫生長中的植物澆水】</span>\n                  </p>\n                  <p className=\"text-slate-500 text-[10px] md:text-xs leading-relaxed font-bold mt-4\">\n                    💡 如果植物今天沒有喝到水，它們的生長進度就會停滯，甚至更容易生病喔！請立刻裝備左側的「單格澆水」去照顧它們吧！\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-blue-500 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-blue-600 transition-colors\">\n                  我知道了，這就去澆水！\n                </button>\n              </div>\n            </div>\n          )}\n\n          {currentEvent?.type === 'tutorial_harvest' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[100]\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar border-4 border-yellow-400\">\n                <div className=\"text-center font-black text-yellow-600 mb-2 animate-pulse\">🎓 新手必讀</div>\n                <div className=\"text-5xl md:text-6xl mb-4 text-center\">✨</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-yellow-900\">大豐收：如何收成？</h2>\n                <div className=\"bg-yellow-50 p-4 rounded-xl md:rounded-2xl mb-6 mt-4\">\n                  <p className=\"text-slate-700 text-[10px] md:text-xs leading-relaxed font-bold\">\n                    恭喜你！農田裡有植物成熟了（會發出閃亮特效 ✨）！\n                  </p>\n                  <p className=\"text-slate-800 text-[10px] md:text-xs leading-relaxed font-black mt-3 bg-yellow-200 p-3 rounded-xl border border-yellow-300\">\n                    1. 找到成熟發光的作物。<br/>\n                    2. <span className=\"text-red-600\">【直接點擊】</span>該作物。<br/>\n                    3. 作物就會自動飛進左側面板的<span className=\"text-red-600\">【📥 收成箱】</span>存入庫存！<br/>\n                    4. 進入右上角「🛒 商店」的販賣區，把它們賣掉換錢吧！\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-yellow-500 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-yellow-600 transition-colors\">\n                  太棒了，馬上來收成！\n                </button>\n              </div>\n            </div>\n          )}\n\n          {currentEvent?.type === 'tutorial_after_harvest' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[100]\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar border-4 border-green-400\">\n                <div className=\"text-center font-black text-green-600 mb-2 animate-pulse\">🎓 新手獎勵</div>\n                <div className=\"text-5xl md:text-6xl mb-4 text-center\">🎁</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-green-900\">鎮長的賀禮！</h2>\n                <div className=\"bg-green-50 p-4 rounded-xl md:rounded-2xl mb-6 mt-4\">\n                  <p className=\"text-slate-700 text-[10px] md:text-xs leading-relaxed font-bold\">\n                    恭喜你完成了第一次全面收成！鎮長特地送來了農業物資獎勵：<br/><br/>\n                    <span className=\"text-green-700 font-black\">【肥料 (葉菜用)】x1</span><br/>\n                    裝備後施打在葉菜類作物上，可以瞬間加速一天的生長進度！<br/><br/>\n                    <span className=\"text-blue-700 font-black\">【防蟲紗網】x1</span><br/>\n                    點擊農田上方的「部署防蟲網」，可以保護整塊農田免受蟲害侵襲！\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-green-500 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-green-600 transition-colors shadow-md\">\n                  收下禮物！\n                </button>\n              </div>\n            </div>\n          )}\n\n          {currentEvent?.type === 'tutorial_special_seed' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[100]\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar border-4 border-purple-400\">\n                <div className=\"text-center font-black text-purple-600 mb-2 animate-pulse\">🎓 傳說現世</div>\n                <div className=\"text-5xl md:text-6xl mb-4 text-center\">✨</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-purple-900\">獲得傳說種子！</h2>\n                <div className=\"bg-purple-50 p-4 rounded-xl md:rounded-2xl mb-6 mt-4\">\n                  <p className=\"text-slate-700 text-[10px] md:text-xs leading-relaxed font-bold\">\n                    太厲害了！你完成了校長的委託！為了表達感謝，校長送給了你一顆極其稀有的<span className=\"text-purple-600 font-black\">【{currentEvent.crop?.name} 種子】</span>！\n                  </p>\n                  <p className=\"text-slate-500 text-[10px] md:text-xs leading-relaxed font-bold mt-4 bg-purple-100 p-2 rounded\">\n                    💡 傳說種子無法在商店購買，把它種在田裡耐心照顧，成熟後販賣可以獲得極大筆利潤喔！\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-purple-500 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-purple-600 transition-colors shadow-md\">\n                  太棒了！\n                </button>\n              </div>\n            </div>\n          )}\n\n          {currentEvent?.type === 'tutorial_bug' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[100]\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar border-4 border-red-400\">\n                <div className=\"text-center font-black text-red-600 mb-2 animate-pulse\">🎓 新手必讀</div>\n                <div className=\"text-5xl md:text-6xl mb-4 text-center\">🐛</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-red-900\">突發狀況：發現害蟲！</h2>\n                <div className=\"bg-red-50 p-4 rounded-xl md:rounded-2xl mb-6 mt-4\">\n                  <p className=\"text-slate-700 text-[10px] md:text-xs leading-relaxed font-bold\">\n                    糟糕！你的農田裡出現了<span className=\"text-red-600 font-black\">【害蟲】</span>。如果在今晚過夜前沒有驅除牠們，被寄生的植物就會被啃食枯死！\n                  </p>\n                  <p className=\"text-slate-800 text-[10px] md:text-xs leading-relaxed font-black mt-3 bg-red-200 p-3 rounded-xl border border-red-300 shadow-inner\">\n                    💡 驅蟲步驟：<br/>\n                    1. 前往「🛒 商店」購買【辣椒水】。<br/>\n                    2. 在左側清單裝備【🌶️ 辣椒水】。<br/>\n                    3. 點擊有害蟲的格子進行驅逐！\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-red-500 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-red-600 transition-colors\">\n                  我知道了，馬上處理！\n                </button>\n              </div>\n            </div>\n          )}\n\n          {currentEvent?.type === 'tutorial_weed' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[100]\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar border-4 border-green-400\">\n                <div className=\"text-center font-black text-green-600 mb-2 animate-pulse\">🎓 新手必讀</div>\n                <div className=\"w-16 h-16 mx-auto mb-4 drop-shadow-md\"><WeedIcon className=\"w-full h-full\" /></div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-green-900\">突發狀況：發現野草！</h2>\n                <div className=\"bg-green-50 p-4 rounded-xl md:rounded-2xl mb-6 mt-4\">\n                  <p className=\"text-slate-700 text-[10px] md:text-xs leading-relaxed font-bold\">\n                    注意！你的農田裡長出了<span className=\"text-green-600 font-black\">【尖刺野草】</span>。雜草會搶走養分，如果不處理，植物明天就會枯死！\n                  </p>\n                  <p className=\"text-slate-800 text-[10px] md:text-xs leading-relaxed font-black mt-3 bg-green-200 p-3 rounded-xl border border-green-300 shadow-inner\">\n                    💡 除草步驟：<br/>\n                    1. 前往「🛒 商店」購買【除草剪刀】。<br/>\n                    2. 在左側清單裝備【✂️ 除草剪刀】。<br/>\n                    3. 點擊有雜草的格子進行割除！\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-green-500 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-green-600 transition-colors\">\n                  我知道了，馬上處理！\n                </button>\n              </div>\n            </div>\n          )}\n\n          {currentEvent?.type === 'tutorial_rain' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[100]\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar border-4 border-blue-400\">\n                <div className=\"text-center font-black text-blue-600 mb-2 animate-pulse\">🎓 新手必讀</div>\n                <div className=\"text-5xl md:text-6xl mb-4 text-center\">🌧️</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-blue-900\">天氣系統：下雨天</h2>\n                <div className=\"bg-blue-50 p-4 rounded-xl md:rounded-2xl mb-6 mt-4\">\n                  <p className=\"text-slate-700 text-[10px] md:text-xs leading-relaxed font-bold\">\n                    太棒了，今天下雨了！在《四季農莊》中，大自然是你最好的幫手。下雨天時，農田會<span className=\"text-blue-600 font-black\">【自動吸滿水分】</span>，你今天不需要花費時間和體力去澆水喔！\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-blue-500 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-blue-600 transition-colors\">\n                  我知道了！\n                </button>\n              </div>\n            </div>\n          )}\n\n          {currentEvent?.type === 'typhoon_warning' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[100]\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar border-4 border-blue-500\">\n                {currentEvent.isFirst && <div className=\"text-center font-black text-blue-600 mb-2 animate-pulse\">🎓 新手必讀</div>}\n                \n                <div className=\"text-5xl md:text-6xl mb-4 text-center\">🌀</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-blue-900\">氣象局：強烈颱風警報！</h2>\n                <div className=\"bg-blue-50 p-4 rounded-xl md:rounded-2xl mb-6 mt-4\">\n                  <p className=\"text-red-600 text-[10px] md:text-xs leading-relaxed font-black mt-2\">\n                    警告：明天將有颱風！田裡「尚未成熟」且「沒有架設防風網」的作物，將有 50% 的機率被摧毀！\n                  </p>\n                  {currentEvent.isFirst && (\n                    <p className=\"text-emerald-700 text-[10px] md:text-xs leading-relaxed font-black mt-3 bg-emerald-100 p-2 rounded-lg border border-emerald-200\">\n                      🎁 政府與農委會緊急發配了防颱物資：【防風網】x1 已存入你的庫存！\n                    </p>\n                  )}\n                  <p className=\"text-slate-800 text-[10px] md:text-xs leading-relaxed font-black mt-3 bg-blue-100 p-3 rounded-xl border border-blue-200 shadow-inner\">\n                    💡 防風網使用教學：<br/>\n                    1. {currentEvent.isFirst ? \"已經有政府送的防風網了！若不夠可前往\" : \"前往\"}右上角「🛒 商店」購買【🛡️ 防風網】。<br/>\n                    2. 進入你的農田區塊（例如第 1 區）。<br/>\n                    3. 點選畫面上方的「部署防風網」。<br/><br/>\n                    <span className=\"text-blue-700\">⚠️ 特別注意：一張防風網可以保護【一整大塊農地（包含裡面的8小格）】，不需要每個格子都買喔！</span>\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-blue-600 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-blue-700 transition-colors\">\n                  我知道了，馬上去準備！\n                </button>\n              </div>\n            </div>\n          )}\n\n          {/* 委託大型事件提示字卡 */}\n          {currentEvent?.type === 'school_quest' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-[100]\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar border-4 border-yellow-400\">\n                {!flags.seenQuest && <div className=\"text-center font-black text-yellow-600 mb-2 animate-pulse\">🎓 經濟學小知識</div>}\n                \n                <div className=\"text-5xl md:text-6xl mb-4 text-center\">🏫</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-yellow-700\">偏鄉小學的營養午餐委託</h2>\n                <div className=\"bg-yellow-50 p-4 rounded-xl md:rounded-2xl mb-6 mt-4 border border-yellow-200\">\n                  <p className=\"text-slate-600 text-[10px] md:text-xs leading-relaxed font-bold\">\n                    當市場上極度需要某樣商品，但供給有限時，價格就會上漲！\n                  </p>\n                  <p className=\"text-slate-800 text-[10px] md:text-xs leading-relaxed font-black mt-2\">\n                    附近的偏鄉小學本週急缺 <span className=\"text-red-600 text-sm md:text-base\">{currentEvent.data?.crop?.icon} {currentEvent.data?.crop?.name}</span>！<br/><br/>\n                    只要在 <span className=\"text-red-600 font-black\">{currentEvent.data?.daysLeft} 天</span> 內交付足夠的數量，校長願意以 <span className=\"bg-yellow-200 px-1 rounded\">3 倍</span> 高價收購！\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-yellow-500 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-yellow-600 transition-colors\">\n                  太棒了，接下委託！\n                </button>\n              </div>\n            </div>\n          )}\n\n          {currentEvent?.type === 'irrigation_upgrade' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-50\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-md w-full shadow-2xl animate-in zoom-in duration-300 max-h-[85vh] overflow-y-auto hide-scrollbar\">\n                <div className=\"text-[10px] md:text-xs font-black text-emerald-600 mb-2 text-center\">📢 農委會補助通知</div>\n                <div className=\"text-5xl md:text-6xl mb-4 text-center\">🚜</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-center text-emerald-700\">科技升級：自動灌溉系統！</h2>\n                <div className=\"bg-emerald-50 p-4 rounded-xl md:rounded-2xl mb-6 mt-4 border border-emerald-200\">\n                  <p className=\"text-slate-600 text-[10px] md:text-xs leading-relaxed font-bold\">\n                    恭喜你度過了初期的艱辛！鑒於你對地方農業的穩定貢獻，政府與農委會特別提撥了一筆專案補助，為你的農莊全面安裝了「自動化灌溉系統」。\n                  </p>\n                  <p className=\"text-slate-800 text-[10px] md:text-xs leading-relaxed font-black mt-2\">\n                    即日起，你的灑水器已升級為 <span className=\"bg-emerald-200 px-1 rounded\">全區灑水</span>！只需點擊一次，就能瞬間為整塊農田（8格）澆滿水！\n                  </p>\n                </div>\n                <button onClick={closeEventModal} className=\"w-full bg-emerald-500 text-white py-3 md:py-4 rounded-xl font-black text-sm md:text-base hover:bg-emerald-600 transition-colors\">\n                  太棒了，收下補助！\n                </button>\n              </div>\n            </div>\n          )}\n\n          {/* 委託交付 Modal */}\n          {showQuestModal && schoolQuest && (\n            <div className=\"fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4 z-50\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] max-w-sm w-full text-center shadow-2xl animate-in zoom-in duration-200\">\n                <div className=\"text-6xl mb-4\">🏫</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-2 text-yellow-700\">偏鄉小學急需食材</h2>\n                <div className=\"bg-yellow-50 p-4 rounded-xl mb-6 border border-yellow-200\">\n                  <p className=\"font-bold text-slate-700 text-sm md:text-base\">\n                    校長需要 <span className=\"text-red-600 text-lg md:text-xl font-black\">{schoolQuest.required}</span> 個 \n                    <span className=\"mx-1\">{schoolQuest.crop.icon}</span>{schoolQuest.crop.name}。\n                  </p>\n                  <p className=\"font-black mt-3 text-yellow-800 text-xs md:text-sm bg-yellow-200 py-2 rounded-lg\">\n                    目前倉庫擁有：{inventory.crops?.[schoolQuest.crop.id] || 0} 個\n                  </p>\n                  <p className=\"text-[10px] text-slate-500 mt-2 font-bold\">交付可獲得3倍市價與神秘種子獎勵！<br/>(剩餘時間: {schoolQuest.daysLeft} 天)</p>\n                </div>\n                <div className=\"flex gap-3\">\n                  <button onClick={() => setShowQuestModal(false)} className=\"flex-1 bg-slate-200 py-3 md:py-4 rounded-xl font-bold text-slate-600 hover:bg-slate-300\">稍後再來</button>\n                  <button \n                    disabled={(inventory.crops?.[schoolQuest.crop.id] || 0) < schoolQuest.required}\n                    onClick={handleQuestDeliver} \n                    className=\"flex-1 bg-yellow-500 py-3 md:py-4 rounded-xl font-black text-white hover:bg-yellow-600 disabled:opacity-50 disabled:bg-slate-300 disabled:hover:bg-slate-300 transition-colors\"\n                  >\n                    立即交付\n                  </button>\n                </div>\n              </div>\n            </div>\n          )}\n\n          {/* 商店彈窗 */}\n          {showShop && (\n            <div className=\"fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center p-2 md:p-4 z-50\">\n              <div className=\"bg-white p-4 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-2xl w-full shadow-2xl animate-in zoom-in duration-200 max-h-[90vh] flex flex-col\">\n                <div className=\"flex justify-between items-center mb-4 border-b pb-3 md:pb-4 shrink-0\">\n                  <div>\n                    <h2 className=\"text-xl md:text-2xl font-black\">🛒 村莊雜貨店</h2>\n                    <div className=\"text-sm font-bold text-yellow-600 mt-1\">擁有的金錢: ${gold.toLocaleString()}</div>\n                  </div>\n                  <div className=\"flex items-center gap-2 md:gap-3\">\n                    <button \n                      onClick={() => { setShowShop(false); setShowModal('gallery'); }} \n                      className=\"bg-indigo-50 text-indigo-700 border-2 border-indigo-100 px-2 md:px-4 py-1.5 md:py-2 rounded-lg md:rounded-xl font-black text-[10px] md:text-sm hover:bg-indigo-100 transition-colors flex items-center gap-1 md:gap-2 active:scale-95\"\n                    >\n                      <span className=\"hidden sm:inline\">📖 收集圖鑑</span>\n                      <span className=\"sm:hidden\">📖 圖鑑</span>\n                    </button>\n                    <button onClick={() => setShowShop(false)} className=\"bg-slate-100 p-1.5 md:p-2 rounded-full hover:bg-slate-200 transition-colors\">❌</button>\n                  </div>\n                </div>\n\n                <div className=\"flex gap-2 md:gap-4 mb-4 shrink-0\">\n                  <button onClick={() => setShopTab('buy')} className={`flex-1 py-2 md:py-3 rounded-xl font-black transition-colors ${shopTab === 'buy' ? 'bg-emerald-600 text-white shadow-md' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>買入物資</button>\n                  <button onClick={() => setShopTab('sell')} className={`flex-1 py-2 md:py-3 rounded-xl font-black transition-colors ${shopTab === 'sell' ? 'bg-yellow-500 text-white shadow-md' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'} ${(tutorialStep >= 7 && !flags.tutSell) && shopTab !== 'sell' ? 'ring-4 ring-yellow-400 animate-pulse' : ''}`}>賣出農產</button>\n                </div>\n                \n                {shopTab === 'buy' && (\n                  <div className=\"grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-8 overflow-y-auto custom-scrollbar flex-1 pr-1 md:pr-2 pb-4\">\n                    <div>\n                      <h3 className=\"text-[10px] md:text-xs font-black text-slate-400 uppercase tracking-widest mb-3 md:mb-4 sticky top-0 bg-white/90 py-1 z-10\">🌱 當季種子包</h3>\n                      <div className=\"space-y-2 md:space-y-3\">\n                        {CROPS[season].map(crop => (\n                          <button\n                            key={crop?.id}\n                            onClick={() => { \n                              if (gold >= crop.price) {\n                                setGold(g => g - crop.price);\n                                setInventory(inv => ({\n                                  ...inv,\n                                  seeds: { ...inv.seeds, [crop.id]: (inv.seeds[crop.id] || 0) + 1 }\n                                }));\n                                playEffect('coin');\n                                setMessage(`購買了 [${crop.name}種子]！請至左側農具清單裝備。`);\n                              } else {\n                                setMessage(\"餘額不足，無法購買這批種子！\");\n                              }\n                            }}\n                            className={`w-full p-3 md:p-4 rounded-xl md:rounded-2xl border-2 hover:border-green-400 hover:bg-green-50 transition-all flex justify-between items-center group ${tutorialStep === 2 && crop.id === 'sweetpotatoleaf' ? 'border-blue-500 animate-pulse bg-blue-50' : 'border-slate-100'}`}\n                          >\n                            <div>\n                              <div className=\"font-black text-base md:text-lg text-left\">{crop.icon} {crop.name}</div>\n                              <div className=\"text-[9px] md:text-[10px] text-slate-400 mt-1 font-bold\">生長 {crop.days} 天 ｜ 單售 ${crop.value}</div>\n                            </div>\n                            <div className=\"bg-green-100 text-green-700 px-2 py-1 md:px-3 md:py-1 rounded-lg md:rounded-xl font-black text-xs md:text-sm group-hover:bg-green-500 group-hover:text-white transition-colors\">\n                              $ {crop.price}\n                            </div>\n                          </button>\n                        ))}\n                      </div>\n                    </div>\n\n                    <div>\n                      <h3 className=\"text-[10px] md:text-xs font-black text-slate-400 uppercase tracking-widest mb-3 md:mb-4 sticky top-0 bg-white/90 py-1 z-10\">🛠️ 農用耗材</h3>\n                      <div className=\"space-y-2 md:space-y-3\">\n                        <div className=\"p-3 md:p-4 rounded-xl md:rounded-2xl border-2 border-slate-100 flex justify-between items-center\">\n                          <div>\n                            <div className=\"font-black text-sm md:text-base flex items-center gap-1\">✂️ 除草剪刀</div>\n                            <div className=\"text-[8px] md:text-[10px] text-slate-400 mt-1 font-bold\">除草 10 次<br/>庫存: {inventory.scissors}</div>\n                          </div>\n                          <button onClick={() => { playEffect('coin'); buyItem('scissors', 100); }} className=\"bg-orange-100 text-orange-700 px-3 md:px-4 py-1.5 md:py-2 rounded-lg font-black text-xs hover:bg-orange-500 hover:text-white transition-all active:scale-95\">$ 100</button>\n                        </div>\n                        \n                        <div className=\"p-3 md:p-4 rounded-xl md:rounded-2xl border-2 border-slate-100 flex justify-between items-center\">\n                          <div>\n                            <div className=\"font-black text-sm md:text-base flex items-center gap-1\">🌶️ 辣椒水</div>\n                            <div className=\"text-[8px] md:text-[10px] text-slate-400 mt-1 font-bold\">驅蟲 10 次<br/>庫存: {inventory.chili}</div>\n                          </div>\n                          <button onClick={() => { playEffect('coin'); buyItem('chili', 100); }} className=\"bg-red-100 text-red-700 px-3 md:px-4 py-1.5 md:py-2 rounded-lg font-black text-xs hover:bg-red-500 hover:text-white transition-all active:scale-95\">$ 100</button>\n                        </div>\n\n                        <div className=\"p-3 md:p-4 rounded-xl md:rounded-2xl border-2 border-slate-100 flex justify-between items-center\">\n                          <div className=\"flex items-center gap-2\">\n                            <FertilizerBag type=\"leaf\" />\n                            <div>\n                              <div className=\"font-black text-sm md:text-base\">氮肥 (葉菜用)</div>\n                              <div className=\"text-[8px] md:text-[10px] text-slate-400 mt-1 font-bold\">庫存: {inventory.fert_leaf}</div>\n                            </div>\n                          </div>\n                          <button onClick={() => { playEffect('coin'); buyItem('fert_leaf', 80); }} className=\"bg-green-100 text-green-700 px-3 md:px-4 py-1.5 md:py-2 rounded-lg font-black text-xs hover:bg-green-500 hover:text-white transition-all active:scale-95\">$ 80</button>\n                        </div>\n\n                        <div className=\"p-3 md:p-4 rounded-xl md:rounded-2xl border-2 border-slate-100 flex justify-between items-center\">\n                          <div className=\"flex items-center gap-2\">\n                            <FertilizerBag type=\"root\" />\n                            <div>\n                              <div className=\"font-black text-sm md:text-base\">磷肥 (根莖用)</div>\n                              <div className=\"text-[8px] md:text-[10px] text-slate-400 mt-1 font-bold\">庫存: {inventory.fert_root}</div>\n                            </div>\n                          </div>\n                          <button onClick={() => { playEffect('coin'); buyItem('fert_root', 120); }} className=\"bg-yellow-100 text-yellow-700 px-3 md:px-4 py-1.5 md:py-2 rounded-lg font-black text-xs hover:bg-yellow-500 hover:text-white transition-all active:scale-95\">$ 120</button>\n                        </div>\n\n                        <div className=\"p-3 md:p-4 rounded-xl md:rounded-2xl border-2 border-slate-100 flex justify-between items-center\">\n                          <div className=\"flex items-center gap-2\">\n                            <FertilizerBag type=\"fruit\" />\n                            <div>\n                              <div className=\"font-black text-sm md:text-base\">鉀肥 (瓜果用)</div>\n                              <div className=\"text-[8px] md:text-[10px] text-slate-400 mt-1 font-bold\">庫存: {inventory.fert_fruit}</div>\n                            </div>\n                          </div>\n                          <button onClick={() => { playEffect('coin'); buyItem('fert_fruit', 300); }} className=\"bg-purple-100 text-purple-700 px-3 md:px-4 py-1.5 md:py-2 rounded-lg font-black text-xs hover:bg-purple-500 hover:text-white transition-all active:scale-95\">$ 300</button>\n                        </div>\n\n                        <div className=\"p-3 md:p-4 rounded-xl md:rounded-2xl border-2 border-slate-100 flex justify-between items-center\">\n                          <div>\n                            <div className=\"font-black text-sm md:text-base flex items-center gap-1\">🕸️ 防蟲紗網</div>\n                            <div className=\"text-[8px] md:text-[10px] text-slate-400 mt-1 font-bold\">保護單一區塊<br/>庫存: {inventory.nets}</div>\n                          </div>\n                          <button onClick={() => { playEffect('coin'); buyItem('net', 100); }} className=\"bg-blue-100 text-blue-700 px-3 md:px-4 py-1.5 md:py-2 rounded-lg font-black text-xs hover:bg-blue-500 hover:text-white transition-all active:scale-95\">$ 100</button>\n                        </div>\n                        \n                        <div className=\"p-3 md:p-4 rounded-xl md:rounded-2xl border-2 border-slate-100 flex justify-between items-center\">\n                          <div>\n                            <div className=\"font-black text-sm md:text-base flex items-center gap-1\">🛡️ 防風網</div>\n                            <div className=\"text-[8px] md:text-[10px] text-slate-400 mt-1 font-bold\">抵禦強風<br/>庫存: {inventory.windbreaks}</div>\n                          </div>\n                          <button onClick={() => { playEffect('coin'); buyItem('windbreak', 1000); }} className=\"bg-emerald-100 text-emerald-700 px-3 md:px-4 py-1.5 md:py-2 rounded-lg font-black text-xs hover:bg-emerald-500 hover:text-white transition-all active:scale-95\">$ 1000</button>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                )}\n\n                {shopTab === 'sell' && (\n                  <div className=\"grid grid-cols-1 md:grid-cols-2 gap-3 md:gap-4 overflow-y-auto custom-scrollbar flex-1 pr-1 md:pr-2 pb-4\">\n                    {Object.entries(inventory.crops || {}).filter(([_, amt]) => amt > 0).length === 0 ? (\n                      <div className=\"col-span-1 md:col-span-2 text-center text-slate-500 py-10 font-bold bg-slate-50 rounded-2xl border-2 border-dashed\">\n                        倉庫空空如也！<br/>快去農田把成熟的作物拖曳到左側的「收成箱」吧！\n                      </div>\n                    ) : (\n                      Object.entries(inventory.crops || {}).map(([cropId, amount]) => {\n                        if (amount <= 0) return null;\n                        const crop = Object.values(CROPS).flat().find(c => c.id === cropId);\n                        if (!crop) return null;\n                        return (\n                          <div key={cropId} className=\"p-3 md:p-4 rounded-xl md:rounded-2xl border-2 border-slate-100 flex justify-between items-center bg-white shadow-sm\">\n                            <div className=\"flex items-center gap-3\">\n                              <div className=\"text-3xl md:text-4xl\">{crop.icon}</div>\n                              <div>\n                                <div className=\"font-black text-sm md:text-base text-slate-800\">{crop.name}</div>\n                                <div className=\"text-[10px] md:text-xs text-slate-500 font-bold mt-1\">\n                                  庫存: <span className=\"text-indigo-600 font-black\">{amount}</span> ｜ 單價: <span className=\"text-yellow-600\">${crop.value.toLocaleString()}</span>\n                                </div>\n                              </div>\n                            </div>\n                            <div className=\"flex flex-col gap-1.5 shrink-0\">\n                              <button onClick={() => sellCrop(cropId, 1, crop.value)} className=\"bg-yellow-100 text-yellow-700 px-3 py-1.5 rounded-lg font-black text-[10px] md:text-xs hover:bg-yellow-500 hover:text-white transition-all active:scale-95 border border-yellow-200\">賣 1 個</button>\n                              {amount > 1 && (\n                                <button onClick={() => sellCrop(cropId, amount, crop.value)} className=\"bg-yellow-500 text-white px-3 py-1.5 rounded-lg font-black text-[10px] md:text-xs hover:bg-yellow-600 transition-all active:scale-95 shadow-sm\">全賣</button>\n                              )}\n                            </div>\n                          </div>\n                        )\n                      })\n                    )}\n                  </div>\n                )}\n              </div>\n            </div>\n          )}\n\n          {/* 圖鑑系統 Modal */}\n          {showModal === 'gallery' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-2 md:p-4 z-50\">\n              <div className=\"bg-white p-5 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-4xl w-full shadow-2xl animate-in zoom-in duration-300 max-h-[95vh] flex flex-col\">\n                <div className=\"flex justify-between items-center mb-4 md:mb-6 border-b pb-3 md:pb-4 shrink-0\">\n                  <h2 className=\"text-xl md:text-2xl font-black text-indigo-900 flex items-center gap-1 md:gap-2\">📖 台灣蔬果農業圖鑑</h2>\n                  <button onClick={() => setShowModal(null)} className=\"bg-slate-100 p-1.5 md:p-2 rounded-full hover:bg-slate-200 transition-colors\">❌</button>\n                </div>\n                \n                <div className=\"overflow-y-auto custom-scrollbar flex-1 pr-2 md:pr-4 pb-4\">\n                  <p className=\"text-[10px] md:text-xs font-bold text-slate-500 mb-4 md:mb-6\">\n                    收集所有四季作物吧！如果在未受蟲害且水分充足的「完美狀態」下收成，還能獲得額外的完美勳章喔！\n                  </p>\n                  \n                  <div className=\"space-y-6 md:space-y-8\">\n                    {Object.entries(CROPS).map(([seasonKey, cropList]) => {\n                      const sName = { SPRING: '春季', SUMMER: '夏季', AUTUMN: '秋季', WINTER: '冬季', SPECIAL: '傳說隱藏' }[seasonKey];\n                      const sColor = { SPRING: 'text-green-600', SUMMER: 'text-yellow-600', AUTUMN: 'text-orange-600', WINTER: 'text-blue-600', SPECIAL: 'text-purple-600' }[seasonKey];\n                      const sBorder = { SPRING: 'border-green-200', SUMMER: 'border-yellow-200', AUTUMN: 'border-orange-200', WINTER: 'border-blue-200', SPECIAL: 'border-purple-300' }[seasonKey];\n                      const sBg = { SPRING: 'bg-green-50/30', SUMMER: 'bg-yellow-50/30', AUTUMN: 'bg-orange-50/30', WINTER: 'bg-blue-50/30', SPECIAL: 'bg-gradient-to-br from-purple-50 to-pink-50' }[seasonKey];\n                      \n                      return (\n                        <div key={seasonKey}>\n                          <h3 className={`text-base md:text-lg font-black mb-3 md:mb-4 border-b-2 inline-block pb-1 ${sColor}`}>\n                            {seasonKey === 'SPECIAL' ? '✨ ' : ''}{sName}作物\n                          </h3>\n                          \n                          <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-3 md:gap-4\">\n                            {cropList.map(crop => {\n                              const record = gallery[crop?.id];\n                              const isUnlocked = !!record?.unlocked;\n                              const isPerfect = !!record?.perfect;\n\n                              return (\n                                <div key={crop?.id} className={`p-4 md:p-5 rounded-xl md:rounded-2xl border-2 flex items-start gap-4 md:gap-5 relative transition-all ${isUnlocked ? `${sBorder} ${sBg}` : 'border-slate-100 bg-slate-50 grayscale opacity-60'}`}>\n                                  \n                                  <div className={`text-5xl md:text-6xl shrink-0 drop-shadow-sm mt-1 ${seasonKey === 'SPECIAL' && isUnlocked ? 'animate-pulse' : ''}`}>\n                                    {isUnlocked ? crop.icon : '❓'}\n                                  </div>\n                                  \n                                  <div className=\"flex-1 min-w-0\">\n                                    <div className={`font-black text-base md:text-lg ${seasonKey === 'SPECIAL' && isUnlocked ? 'text-purple-800' : 'text-slate-700'}`}>\n                                      {isUnlocked ? crop.name : '未知作物'}\n                                    </div>\n                                    \n                                    {isUnlocked ? (\n                                      <>\n                                        <div className=\"text-[10px] md:text-[11px] text-indigo-700 font-black mt-1.5 bg-indigo-100/50 inline-block px-2 py-0.5 rounded border border-indigo-200\">\n                                          ⏳ 生長期：{crop.days} 天 ｜ {crop.type === 'leaf' ? '🌿 葉菜類' : crop.type === 'root' ? '🥔 根莖類' : '🍎 瓜果類'}\n                                        </div>\n                                        <div className=\"text-[10px] md:text-[11px] text-slate-600 mt-2 leading-relaxed whitespace-pre-line font-medium\">\n                                          {crop.desc}\n                                        </div>\n                                      </>\n                                    ) : (\n                                      <div className=\"text-[10px] md:text-xs font-bold text-slate-400 mt-1 md:mt-2 uppercase tracking-widest\">未解鎖</div>\n                                    )}\n                                  </div>\n                                  \n                                  {isPerfect && (\n                                    <div className=\"absolute -top-2 -right-2 bg-yellow-400 border-2 border-white w-6 h-6 md:w-8 md:h-8 rounded-full flex items-center justify-center shadow-md animate-bounce text-[10px] md:text-[12px]\" title=\"完美收成勳章\">\n                                      ✨\n                                    </div>\n                                  )}\n                                </div>\n                              );\n                            })}\n                          </div>\n                        </div>\n                      );\n                    })}\n                  </div>\n                </div>\n              </div>\n            </div>\n          )}\n\n          {/* 睡覺與存檔確認彈窗 */}\n          {showModal === 'sleep' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-sm flex items-center justify-center p-4 z-50\">\n              <div className=\"bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] max-w-sm w-full text-center shadow-2xl animate-in zoom-in duration-200\">\n                <div className=\"text-5xl md:text-6xl mb-3 md:mb-4\">🌙</div>\n                <h2 className=\"text-xl md:text-2xl font-black mb-3 md:mb-4\">準備休息了嗎？</h2>\n                <p className=\"text-slate-500 mb-5 md:mb-6 font-bold text-[10px] md:text-xs leading-relaxed\">\n                  請確認所有作物都已澆水，並且<span className=\"text-red-500\">沒有未處理的蟲害或雜草</span>，否則作物在夜晚會直接枯死喔！\n                </p>\n                <div className=\"flex gap-3 md:gap-4\">\n                  <button onClick={() => setShowModal(null)} className=\"flex-1 bg-slate-100 text-slate-600 py-3 md:py-4 rounded-xl md:rounded-2xl font-black text-sm md:text-base hover:bg-slate-200 transition-colors\">\n                    再巡一下\n                  </button>\n                  <button onClick={processNextDay} className=\"flex-1 bg-slate-800 text-white py-3 md:py-4 rounded-xl md:rounded-2xl font-black text-sm md:text-base hover:bg-slate-700 transition-colors\">\n                    確定睡覺\n                  </button>\n                </div>\n                \n                <div className=\"flex flex-col gap-3 md:gap-4 w-full mt-6 pt-6 border-t border-slate-100\">\n                  <div className=\"text-[10px] md:text-xs font-black text-slate-400 uppercase tracking-widest mb-1\">系統存檔 (支援手機/平板瀏覽器)</div>\n                  <div className=\"flex gap-3 md:gap-4\">\n                    <button onClick={handleSave} className=\"flex-1 bg-blue-100 text-blue-700 py-3 rounded-xl font-black text-sm hover:bg-blue-200 transition-colors active:scale-95 shadow-sm\">\n                      💾 儲存進度\n                    </button>\n                  </div>\n                </div>\n              </div>\n            </div>\n          )}\n\n          {/* 結算彈窗 */}\n          {showModal === 'contest' && (\n            <div className=\"fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 z-50\">\n              <div className=\"bg-white p-8 md:p-10 rounded-[2.5rem] md:rounded-[3rem] max-w-sm w-full text-center shadow-2xl animate-in zoom-in\">\n                <div className=\"text-6xl md:text-7xl mb-4 md:mb-6\">🥇</div>\n                <h2 className=\"text-xl md:text-3xl font-black mb-2 uppercase\">季度大賽</h2>\n                <p className=\"text-slate-400 text-[10px] md:text-xs mb-6 md:mb-8 font-bold\">你在第 {day} 天的表現非常驚人，評審團給予了高度評價！</p>\n                <div className=\"bg-slate-100 p-4 md:p-6 rounded-2xl md:rounded-3xl mb-6 md:mb-8\">\n                  <div className=\"text-[9px] md:text-[10px] font-black text-slate-400 mb-1 uppercase\">季度獎金</div>\n                  <div className=\"text-3xl md:text-4xl font-black text-yellow-600\">${Math.floor(gold * 0.2).toLocaleString()}</div>\n                </div>\n                <button onClick={() => { setGold(g => g + Math.floor(g * 0.2)); setShowModal(null); playEffect('coin'); }} className=\"w-full bg-slate-800 text-white py-4 md:py-5 rounded-xl md:rounded-2xl font-black uppercase tracking-widest hover:bg-slate-700 transition-all\">領取獎勵</button>\n              </div>\n            </div>\n          )}\n\n          {/* 遊戲結束結果 */}\n          {showModal === 'result' && (\n            <div className=\"fixed inset-0 bg-slate-900/95 backdrop-blur-xl flex items-center justify-center p-4 z-50\">\n              <div className=\"bg-white p-8 md:p-12 rounded-[2.5rem] md:rounded-[3.5rem] max-w-lg w-full text-center shadow-2xl overflow-y-auto max-h-[90vh] hide-scrollbar\">\n                <div className=\"text-[10px] md:text-xs font-black text-slate-400 uppercase tracking-widest mb-3 md:mb-4\">365天經營結算</div>\n                <h1 className=\"text-4xl md:text-5xl font-black mb-6 md:mb-8 italic\">農莊年度結算</h1>\n                <div className=\"grid grid-cols-2 gap-3 md:gap-4 mb-8 md:mb-10\">\n                  <div className=\"bg-slate-50 p-6 md:p-8 rounded-2xl md:rounded-3xl border border-slate-100\">\n                    <div className=\"text-[9px] md:text-[10px] font-black text-slate-400 mb-1 md:mb-2 uppercase\">總資產</div>\n                    <div className=\"text-xl md:text-3xl font-black font-mono text-slate-800\">${gold.toLocaleString()}</div>\n                  </div>\n                  <div className=\"bg-blue-600 p-6 md:p-8 rounded-2xl md:rounded-3xl text-white shadow-xl shadow-blue-200\">\n                    <div className=\"text-[9px] md:text-[10px] font-black opacity-60 mb-1 md:mb-2 uppercase\">最終評級</div>\n                    <div className=\"text-5xl md:text-6xl font-black\">{gold > 1000000 ? 'S' : gold > 500000 ? 'A' : gold > 100000 ? 'B' : 'C'}</div>\n                  </div>\n                </div>\n                <button onClick={() => {\n                  localStorage.removeItem('farm_tycoon_save_v2'); \n                  window.location.reload();\n                }} className=\"w-full bg-slate-800 text-white py-5 md:py-6 rounded-2xl md:rounded-3xl font-black text-sm md:text-base uppercase tracking-widest hover:bg-slate-700 active:scale-95 transition-all\">刪除存檔並開啟下一個循環</button>\n              </div>\n            </div>\n          )}\n        </div>\n      );\n    };\n\n    const root = ReactDOM.createRoot(document.getElementById('root'));\n    root.render(<App />);\n  </script>\n    <script src=\"farm-ui.js\"></script>\n</body>\n</html>\n";

export function mount(root, context = {}) {
  return mountEmbeddedPage(root, {
    html: pageHtml,
    baseUrl: new URL('../../', import.meta.url).href,
    title: String(context.game?.title || '科學農場互動遊戲')
  });
}
